-- RALLY 100 v1 — APPLY. Paste this whole file into the Supabase SQL editor
-- (as postgres) and run it once. GENERATED by rally-100/db/build-apply.sh
-- from db/migrations/1001_rally100_v1.sql; edit the migration, never this.
--
-- ALL OR NOTHING. It is one transaction: if any statement fails, nothing is
-- left behind and RALLY is exactly as it was. It creates schema rally100 and
-- touches nothing in RALLY's public schema. It is not re-runnable: a second
-- run stops at `create schema rally100` and changes nothing.
--
-- AFTER IT COMMITS:
--   1. Project Settings -> Data API -> Exposed schemas: add rally100.
--   2. Check: `select count(*) from pg_proc p join pg_namespace n
--      on n.oid = p.pronamespace where n.nspname = 'rally100'
--      and has_function_privilege('authenticated', p.oid, 'execute');`
--      must answer 39.
-- TO UNDO: rally-100/db/ROLLBACK_rally100_v1.sql (removes RALLY 100 only).

begin;

-- RALLY 100 v1 — the recruiting app's backend, in a schema of its own.
--
-- WHAT THIS FILE IS. One migration that creates schema `rally100` and
-- everything RALLY 100 needs inside it: sixteen tables, the thirty-nine
-- functions a client may call (rally-100/app/API.md section 6) and the
-- internal helpers they stand on. API.md is the contract; this file is that
-- contract made executable, and rally-100/db/test/rally100-test.sql checks
-- the two against each other.
--
-- WHAT IT TOUCHES IN RALLY: NOTHING. No table, column, function, trigger,
-- policy or grant in `public`, `auth` or `realtime` is created or altered.
-- RALLY 100 READS public.profiles, public.teams and auth.uid(), and that is
-- the whole of the contact surface. For the same reason there is no foreign
-- key from a rally100 table to public.profiles: a foreign key installs
-- referential-integrity triggers ON THE REFERENCED TABLE, which would be an
-- alteration of RALLY's profiles table, and it would make deleting an auth
-- user depend on RALLY 100. Rep ids here are soft references, exactly as
-- RALLY's own pin_id / territory_id are (0001).
-- rally-100/db/ROLLBACK_rally100_v1.sql removes all of it with one
-- `drop schema rally100 cascade`.
--
-- RPC ONLY. A client never reads or writes a rally100 table. Every table has
-- RLS enabled with NO policies and NO grants to any client role, so even a
-- mistaken future grant would read zero rows. Every client operation is a
-- function below, and every one of them is a door that bypasses RLS by
-- construction, so each one:
--   * derives the caller's identity, team and role server-side, every call
--     (rally100._caller()), and never accepts any of them from the client;
--   * checks scope before every read and every write, and answers an id
--     outside scope exactly as it answers an id that does not exist
--     (`rally100: not_found`), so a guessed UUID learns nothing;
--   * builds no SQL from client input — there is no dynamic SQL in this file;
--   * runs SECURITY DEFINER with `search_path = ''`, so every identifier is
--     schema-qualified or the function does not compile. That includes the
--     TYPE names inside function bodies (pg_catalog.jsonb, pg_catalog.uuid,
--     ...): with an empty path PostgreSQL still searches the caller's
--     temporary schema FIRST for relation and type names, so an unqualified
--     `jsonb` could be a type the caller planted. Keyword types (integer,
--     boolean, bigint, smallint) are qualified by the grammar itself.
--     db/test/shadow-test.sql plants such shadows and proves none of this
--     file's code resolves to them (with a negative control).
--
-- ERRORS. Authorization refusals use errcode 42501, validation refusals
-- 22023. The message is always `rally100: <token>` and nothing else: the
-- client extracts the token and shows its own wording, never database text.
-- The three identity refusals keep the contract's exact spelling
-- (`not signed in`, `no team`, `disabled`); every other token is snake_case.
-- The full token list is in API.md, "Implementation notes".
--
-- MONEY is integer cents with a currency. The reward ledger
-- (rally100.reward_events) and the audit log (rally100.audit) are
-- append-only: no function updates or deletes them, and a trigger refuses
-- UPDATE, DELETE and TRUNCATE even from the table owner.

create schema rally100;
comment on schema rally100 is
  'RALLY 100 (recruiting). RPC only: clients call rally100.<function>, never a table. See rally-100/app/API.md.';

-- ================================================================ tables ===
-- Times written by the server use clock_timestamp(), not now(): "the newer
-- entry" decides which duplicate is held, and "the earliest recorded
-- introduction" decides who is paid a referral, so two writes inside one
-- transaction must still be ordered by when they actually happened.

-- A Person is the master-CRM record of one human. Org-wide, never deleted.
create table rally100.persons (
  id                 uuid primary key default gen_random_uuid(),
  first_name         text not null default '',
  last_name          text not null default '',
  stage              text not null default 'added'
                     check (stage in ('added','intro_planned','introduced','meeting_scheduled',
                                      'meeting_completed','commitment_confirmed','agreement_signed',
                                      'start_confirmed','arrived')),
  outcome            text check (outcome in ('follow_up','not_interested','do_not_contact')),
  outcome_date       date,
  outcome_note       text not null default '',
  interest           text not null default 'unknown'
                     check (interest in ('unknown','interested','maybe','not_interested')),
  responsible_leader uuid,
  next_action        text not null default '',
  next_action_owner  uuid,
  next_action_date   date,
  meeting_at         timestamptz,
  meeting_how        text not null default '',
  meeting_note       text not null default '',
  start_date         date,
  travel_note        text not null default '',
  travel_na          boolean not null default false,
  merged_into        uuid references rally100.persons(id),
  created_at         timestamptz not null default clock_timestamp(),
  updated_at         timestamptz not null default clock_timestamp(),
  check (merged_into is distinct from id)
);
create index persons_merged_idx on rally100.persons (merged_into) where merged_into is not null;

-- A List Entry is one rep's record of one contact. The id is generated on the
-- phone, so a retried create (the outbox replaying after a dropped signal) is
-- an update of the same row, never a second contact.
create table rally100.entries (
  id           uuid primary key,
  team_id      uuid not null,              -- the rep's team when the entry was made (a snapshot)
  rep_id       uuid not null,
  person_id    uuid references rally100.persons(id),
  first_name   text not null default '',
  last_name    text not null default '',
  phone        text not null default '' check (phone ~ '^(\d{10})?$'),
  handle       text not null default '',
  platform     text not null default ''
               check (platform in ('','Instagram','Snapchat','TikTok','Facebook','X','LinkedIn','Discord','Other')),
  other_app    text not null default '',
  tags         text[] not null default '{}'
               check (tags <@ array['School','Sports','Work','Gym','Neighborhood','Family','Group chat',
                                    'Hobbies/Clubs/Community','Lost touch','Other']::text[]),
  notes        text not null default '',
  scene        text check (scene in ('phone','chats','shift','lunch','bus','gym','street','lost',
                                     'family','clubs','roommates','bignight','plusone','mutual')),
  chain_hit    boolean not null default false,
  held_of      uuid references rally100.entries(id),
  kept_with    uuid[] not null default '{}',
  kept_reason  text not null default '',
  merged_into  uuid references rally100.entries(id),
  removed_at   timestamptz,
  completed_at timestamptz,                -- the first moment this entry counted; never cleared
  verified_at  timestamptz,
  verified_by  uuid,
  created_at   timestamptz not null default clock_timestamp(),
  updated_at   timestamptz not null default clock_timestamp(),
  -- Complete is a fact about the stored fields, so the database computes it
  -- rather than trusting anyone to keep a flag in step with them.
  is_complete  boolean generated always as (
                 first_name <> '' and last_name <> '' and char_length(phone) = 10
                 and handle <> '' and platform <> ''
                 and (platform <> 'Other' or other_app <> '')) stored,
  check (held_of is distinct from id),
  check (merged_into is null or removed_at is not null)
);
create index entries_rep_idx    on rally100.entries (rep_id, created_at, id);
create index entries_person_idx on rally100.entries (person_id) where person_id is not null;

-- Every phone and every <platform>:<handle> any entry has carried, per
-- Person. Differing values never overwrite each other; they accumulate.
create table rally100.person_identifiers (
  person_id uuid not null references rally100.persons(id),
  kind      text not null check (kind in ('phone','handle')),
  value     text not null check (value <> ''),
  primary key (kind, value, person_id)
);
create index person_identifiers_person_idx on rally100.person_identifiers (person_id);

-- A strong signal (phone or handle) that met a different last name. Software
-- proposes; a leader decides. Never a silent merge of an ambiguous record.
create table rally100.possible_matches (
  id          uuid primary key default gen_random_uuid(),
  person_a    uuid not null references rally100.persons(id),
  person_b    uuid not null references rally100.persons(id),
  signal      text not null check (signal in ('phone','handle')),
  status      text not null default 'open' check (status in ('open','linked','dismissed')),
  created_at  timestamptz not null default clock_timestamp(),
  resolved_by uuid,
  resolved_at timestamptz,
  check (person_a <> person_b)
);
-- one row per unordered pair, whichever side was found first
create unique index possible_matches_pair_idx
  on rally100.possible_matches (least(person_a, person_b), greatest(person_a, person_b));

-- One introduction record per (Person, rep). recorded_at is SERVER time and
-- is set once: it is what "whoever signs the person first" is measured by,
-- so neither a typed date nor a re-save can move it.
create table rally100.introductions (
  id          uuid primary key default gen_random_uuid(),
  person_id   uuid not null references rally100.persons(id),
  rep_id      uuid not null,
  entry_id    uuid references rally100.entries(id),
  status      text not null check (status in ('planned','introduced')),
  channel     text check (channel in ('text','call','in_person','other')),
  said        text check (said in ('in','maybe','not_for_them','didnt_say')),
  note        text not null default '',
  intro_date  date,
  recorded_at timestamptz,
  received_by uuid,
  received_at timestamptz,
  unique (person_id, rep_id),
  check (status = 'introduced' or (recorded_at is null and received_at is null)),
  check (received_at is null or recorded_at is not null)
);
create index introductions_rep_idx on rally100.introductions (rep_id);

-- The four referral requirements, each confirmed separately by a person.
-- A stage change never writes here.
create table rally100.requirements (
  person_id    uuid not null references rally100.persons(id),
  req          smallint not null check (req between 1 and 4),
  confirmed    boolean not null default false,
  confirmed_by uuid,
  event_date   date,
  note         text not null default '',
  updated_at   timestamptz not null default clock_timestamp(),
  primary key (person_id, req)
);

-- "Something wrong? Tell your leader."
create table rally100.messages (
  id         uuid primary key default gen_random_uuid(),
  person_id  uuid not null references rally100.persons(id),
  rep_id     uuid not null,
  body       text not null check (char_length(body) between 1 and 1000),
  created_at timestamptz not null default clock_timestamp(),
  read_by    uuid,
  read_at    timestamptz
);
create index messages_person_idx on rally100.messages (person_id);
create index messages_unread_idx on rally100.messages (created_at) where read_at is null;

-- Leader notes on a Person: append-only.
create table rally100.notes (
  id         uuid primary key default gen_random_uuid(),
  person_id  uuid not null references rally100.persons(id),
  author     uuid not null,
  body       text not null check (char_length(body) between 1 and 2000),
  created_at timestamptz not null default clock_timestamp()
);
create index notes_person_idx on rally100.notes (person_id);

-- XP is game progress, never money. The primary key IS the anti-farming
-- rule: a (rep, key) pair can be earned once, ever.
create table rally100.xp_events (
  rep_id     uuid not null,
  key        text not null,
  points     integer not null check (points >= 0),
  kind       text not null,
  created_at timestamptz not null default clock_timestamp(),
  primary key (rep_id, key)
);

create table rally100.badges (
  rep_id     uuid not null,
  badge      text not null
             check (badge in ('reader','full','first_intro','matchmaker','sprinter','clean_sweep')),
  created_at timestamptz not null default clock_timestamp(),
  primary key (rep_id, badge)
);

-- "Who sees your contacts": the acknowledgment, per disclosure version.
create table rally100.acks (
  rep_id      uuid not null,
  version     integer not null check (version >= 1),
  accepted_at timestamptz not null default clock_timestamp(),
  primary key (rep_id, version)
);

create table rally100.incentives (
  id          uuid primary key default gen_random_uuid(),
  name        text not null check (char_length(name) between 1 and 80),
  pictures    jsonb not null default '[]'::jsonb
              check (jsonb_typeof(pictures) = 'array' and jsonb_array_length(pictures) <= 4),
  prize_cents integer not null check (prize_cents >= 0),
  how_to_earn text not null default '' check (char_length(how_to_earn) <= 200),
  status      text not null default 'draft' check (status in ('draft','published','off')),
  created_by  uuid not null,
  created_at  timestamptz not null default clock_timestamp(),
  updated_at  timestamptz not null default clock_timestamp(),
  check (status <> 'published' or jsonb_array_length(pictures) >= 1)
);

-- The reward record. Status moves only through the functions below; every
-- move also appends to reward_events. A reversal is a FLAG (reversed_at),
-- never a sixth status, so the record keeps the last status it reached.
create table rally100.rewards (
  id              uuid primary key default gen_random_uuid(),
  kind            text not null check (kind in ('list','referral','incentive')),
  team_id         uuid not null,           -- the credited rep's team when credited (a snapshot)
  rep_id          uuid,                    -- credited rep; null for a referral until credited
  person_id       uuid references rally100.persons(id),
  incentive_id    uuid references rally100.incentives(id),
  amount_cents    integer not null check (amount_cents >= 0),
  currency        text not null default 'USD' check (currency = 'USD'),
  status          text not null
                  check (status in ('in_progress','ready','approved','paid','needs_correction')),
  flags           text[] not null default '{}' check (flags <@ array['no_intro']::text[]),
  spot_check_id   uuid,
  approved_by     uuid,
  approved_at     timestamptz,
  paid_on         date,
  paid_method     text,
  paid_reference  text,
  paid_by         uuid,
  reversed_at     timestamptz,
  reversed_by     uuid,
  reversed_reason text,                    -- internal; never returned to a rep
  rep_reason      text,                    -- rep-facing; may be empty
  correction_note text,
  correction_by   uuid,
  created_at      timestamptz not null default clock_timestamp(),
  updated_at      timestamptz not null default clock_timestamp(),
  check (kind <> 'list'      or (rep_id is not null and person_id is null and incentive_id is null)),
  check (kind <> 'referral'  or (person_id is not null and incentive_id is null)),
  check (kind <> 'incentive' or (rep_id is not null and incentive_id is not null and person_id is null)),
  -- nothing gets past In progress without a credited rep
  check (status = 'in_progress' or rep_id is not null),
  check (status not in ('approved','paid') or (approved_by is not null and approved_at is not null)),
  check (status <> 'paid' or (paid_on is not null and paid_by is not null and coalesce(paid_method, '') <> ''))
);
-- THE ONE-PER RULES, as the database's own constraints rather than a check
-- in a function: one List Completion reward per rep, ever; one Referral
-- reward per Person, ever. They hold against a race, a retry, a bug in a
-- later function, and a direct insert by the table owner.
create unique index rewards_one_list_per_rep        on rally100.rewards (rep_id)    where kind = 'list';
create unique index rewards_one_referral_per_person on rally100.rewards (person_id) where kind = 'referral';
create index rewards_rep_idx    on rally100.rewards (rep_id);
create index rewards_status_idx on rally100.rewards (status);

-- The reward ledger: one row per transition, append-only.
create table rally100.reward_events (
  id          bigserial primary key,
  reward_id   uuid not null references rally100.rewards(id),
  action      text not null,
  from_status text,
  to_status   text,
  actor       uuid,                        -- null = the server itself (e.g. the count reached 100)
  note        text not null default '',
  created_at  timestamptz not null default clock_timestamp()
);
create index reward_events_reward_idx on rally100.reward_events (reward_id, id);

create table rally100.spot_checks (
  id         uuid primary key default gen_random_uuid(),
  reward_id  uuid not null references rally100.rewards(id),
  rep_id     uuid not null,
  leader_id  uuid not null,
  results    jsonb not null check (jsonb_typeof(results) = 'array'),
  note       text not null default '',
  created_at timestamptz not null default clock_timestamp()
);
create index spot_checks_reward_idx on rally100.spot_checks (reward_id);
alter table rally100.rewards
  add constraint rewards_spot_check_fk foreign key (spot_check_id) references rally100.spot_checks(id);

-- Every write appends here: who, which team, what, and the detail.
create table rally100.audit (
  id         bigserial primary key,
  actor      uuid,
  team_id    uuid,
  entity     text not null,
  entity_id  uuid,
  action     text not null,
  detail     jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default clock_timestamp()
);
create index audit_entity_idx on rally100.audit (entity, entity_id, id);
create index audit_actor_idx  on rally100.audit (actor, created_at);

-- ============================================ RLS: on, with no policies ===
-- RLS with no policy reads and writes zero rows for every role that does not
-- own the table. The only path in is a SECURITY DEFINER function, which runs
-- as the owner. Not FORCE: forcing would shut the functions out as well.
alter table rally100.persons            enable row level security;
alter table rally100.entries            enable row level security;
alter table rally100.person_identifiers enable row level security;
alter table rally100.possible_matches   enable row level security;
alter table rally100.introductions      enable row level security;
alter table rally100.requirements       enable row level security;
alter table rally100.messages           enable row level security;
alter table rally100.notes              enable row level security;
alter table rally100.xp_events          enable row level security;
alter table rally100.badges             enable row level security;
alter table rally100.acks               enable row level security;
alter table rally100.incentives         enable row level security;
alter table rally100.rewards            enable row level security;
alter table rally100.reward_events      enable row level security;
alter table rally100.spot_checks        enable row level security;
alter table rally100.audit              enable row level security;

-- ================================================= append-only guard ===
/* The ledger, the audit log, the XP keys, leader notes and spot-checks are
   history. The functions only ever INSERT into them; this trigger makes
   that a property of the tables, so not even the owner (or a future
   function written in a hurry) can rewrite or erase a row. Corrections are
   new rows. */
create function rally100._append_only()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  raise exception 'rally100: append_only' using errcode = '42501',
    detail = pg_catalog.format('%s on rally100.%s is refused: the table is append-only', tg_op, tg_table_name);
end $$;

create trigger audit_append_only before update or delete on rally100.audit
  for each row execute function rally100._append_only();
create trigger audit_no_truncate before truncate on rally100.audit
  for each statement execute function rally100._append_only();
create trigger reward_events_append_only before update or delete on rally100.reward_events
  for each row execute function rally100._append_only();
create trigger reward_events_no_truncate before truncate on rally100.reward_events
  for each statement execute function rally100._append_only();
create trigger xp_events_append_only before update or delete on rally100.xp_events
  for each row execute function rally100._append_only();
create trigger xp_events_no_truncate before truncate on rally100.xp_events
  for each statement execute function rally100._append_only();
create trigger notes_append_only before update or delete on rally100.notes
  for each row execute function rally100._append_only();
create trigger notes_no_truncate before truncate on rally100.notes
  for each statement execute function rally100._append_only();
create trigger spot_checks_append_only before update or delete on rally100.spot_checks
  for each row execute function rally100._append_only();
create trigger spot_checks_no_truncate before truncate on rally100.spot_checks
  for each statement execute function rally100._append_only();

-- ========================================================== small helpers ===
-- Ordered so that every SQL-language body only names functions defined above
-- it (SQL bodies are checked when they are created; PL/pgSQL bodies are not).

create function rally100._fail(p_code text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  raise exception 'rally100: %', p_code using errcode = '22023';
end $$;

create function rally100._deny(p_code text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  raise exception 'rally100: %', p_code using errcode = '42501';
end $$;

/* WHO IS CALLING, derived and never accepted. Raises rather than returning
   null, because every caller treats a failure as fatal and one shared
   refusal keeps the three messages identical everywhere. The order matters:
   a disabled account is told it is disabled even when it also has no team. */
create function rally100._caller()
returns public.profiles
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid pg_catalog.uuid := auth.uid();
  v_me  public.profiles;
begin
  if v_uid is null then
    raise exception 'rally100: not signed in' using errcode = '42501';
  end if;
  select * into v_me from public.profiles where id = v_uid;
  if not found then
    raise exception 'rally100: not signed in' using errcode = '42501';
  end if;
  if v_me.disabled then
    raise exception 'rally100: disabled' using errcode = '42501';
  end if;
  if v_me.team_id is null then
    raise exception 'rally100: no team' using errcode = '42501';
  end if;
  return v_me;
end $$;

-- leader means leader OR manager (RALLY's role list); the owner is above both
create function rally100._require_leader(p_me public.profiles)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if p_me.role not in ('leader', 'manager', 'owner') then
    raise exception 'rally100: not_allowed' using errcode = '42501';
  end if;
end $$;

create function rally100._require_owner(p_me public.profiles)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if p_me.role <> 'owner' then
    raise exception 'rally100: owner_only' using errcode = '42501';
  end if;
end $$;

-- The name shown for a profile: its name, else the part of the email before @.
create function rally100._name(p_uid uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select coalesce(nullif(pg_catalog.btrim(p.name), ''), pg_catalog.split_part(p.email, '@', 1))
       from public.profiles p where p.id = p_uid), '')
$$;

create function rally100._person_name(p_person uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select pg_catalog.btrim(p.first_name || ' ' || p.last_name) from rally100.persons p where p.id = p_person), '')
$$;

/* ONE ORG DAY. "Today" (follow-ups due, the day's spot-check sample, a
   default event date) is the date in ONE organisation timezone, never the
   server's UTC date and never a device's. This is the only place it is set. */
create function rally100._today()
returns date
language sql
stable
security definer
set search_path = ''
as $$
  select (pg_catalog.now() at time zone 'America/Chicago')::pg_catalog.date
$$;

create function rally100._stage_ix(p_stage text)
returns integer
language sql
immutable
security definer
set search_path = ''
as $$
  select pg_catalog.array_position(
    array['added','intro_planned','introduced','meeting_scheduled','meeting_completed',
          'commitment_confirmed','agreement_signed','start_confirmed','arrived']::pg_catalog.text[],
    p_stage)
$$;

create function rally100._tags()
returns text[]
language sql
immutable
security definer
set search_path = ''
as $$
  select array['School','Sports','Work','Gym','Neighborhood','Family','Group chat',
               'Hobbies/Clubs/Community','Lost touch','Other']::pg_catalog.text[]
$$;

create function rally100._scenes()
returns table (scene text, clears_at integer)
language sql
immutable
security definer
set search_path = ''
as $$
  values ('phone', 5), ('chats', 5), ('shift', 3), ('lunch', 3), ('bus', 3), ('gym', 3),
         ('street', 3), ('lost', 3), ('family', 3), ('clubs', 3), ('roommates', 3),
         ('bignight', 3), ('plusone', 3), ('mutual', 3)
$$;

/* The identity of a social account: <platform>:<handle>, or for Other
   Other:<app>:<handle>, so "@marcus on Instagram" and "@marcus on TikTok" are
   different accounts and two typed spellings of one app name are not. */
create function rally100._handle_key(p_platform text, p_handle text, p_other_app text)
returns text
language sql
immutable
security definer
set search_path = ''
as $$
  select case
    when coalesce(p_handle, '') = '' or coalesce(p_platform, '') = '' then null
    when p_platform = 'Other'
      then 'Other:' || pg_catalog.lower(pg_catalog.btrim(coalesce(p_other_app, ''))) || ':' || p_handle
    else p_platform || ':' || p_handle
  end
$$;

create function rally100._level(p_xp integer)
returns jsonb
language sql
immutable
security definer
set search_path = ''
as $$
  with l(name, min) as (
    values ('Rookie', 0), ('Scout', 150), ('Connector', 400), ('Operator', 800),
           ('Prowler', 1300), ('Apex', 2000))
  select pg_catalog.jsonb_build_object(
    'name',      (select l.name from l where l.min <= coalesce(p_xp, 0) order by l.min desc limit 1),
    'min',       (select l.min  from l where l.min <= coalesce(p_xp, 0) order by l.min desc limit 1),
    'next_name', (select l.name from l where l.min >  coalesce(p_xp, 0) order by l.min limit 1),
    'next_min',  (select l.min  from l where l.min >  coalesce(p_xp, 0) order by l.min limit 1))
$$;

-- the first leader of a team, by account age: the default responsible leader
create function rally100._team_leader(p_team uuid)
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select p.id from public.profiles p
   where p.team_id = p_team and p.role in ('leader', 'manager') and not p.disabled
   order by p.created_at, p.id
   limit 1
$$;

/* Every write to one rep's list takes this lock first. The duplicate check
   compares an entry with ALL of the rep's other entries, so two saves of the
   same rep must not interleave (two phones, or an outbox replay racing a
   live save); different reps never wait on each other. */
create function rally100._lock_rep(p_rep uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  select pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rally100.rep:' || p_rep::pg_catalog.text, 0))
$$;

create function rally100._audit(p_actor uuid, p_team uuid, p_entity text, p_entity_id uuid,
                                p_action text, p_detail jsonb)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into rally100.audit (actor, team_id, entity, entity_id, action, detail)
  values (p_actor, p_team, p_entity, p_entity_id, p_action, coalesce(p_detail, '{}'::pg_catalog.jsonb))
$$;

create function rally100._reward_event(p_reward uuid, p_action text, p_from text, p_to text,
                                       p_actor uuid, p_note text)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into rally100.reward_events (reward_id, action, from_status, to_status, actor, note)
  values (p_reward, p_action, p_from, p_to, p_actor, coalesce(p_note, ''))
$$;

-- Earn an XP key. True only the first time; the primary key makes a second
-- grant of the same key impossible rather than merely unlikely.
create function rally100._xp(p_rep uuid, p_key text, p_points integer, p_kind text)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into rally100.xp_events (rep_id, key, points, kind)
  values (p_rep, p_key, p_points, p_kind)
  on conflict (rep_id, key) do nothing;
  return found;
end $$;

create function rally100._xp_total(p_rep uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(pg_catalog.sum(x.points), 0)::integer from rally100.xp_events x where x.rep_id = p_rep
$$;

/* THE COUNT (rule 3). Counted = complete, not removed, not held as a
   duplicate, and its Person not marked do_not_contact. It is a query over
   the rep's entries every time, never a stored counter, so nothing can make
   it drift from the entries it describes. */
create function rally100._rep_counts(p_rep uuid)
returns table (o_count integer, o_drafts integer, o_held integer)
language sql
stable
security definer
set search_path = ''
as $$
  select pg_catalog.count(*) filter (where e.is_complete and e.held_of is null
                                       and coalesce(p.outcome, '') <> 'do_not_contact')::integer,
         pg_catalog.count(*) filter (where not e.is_complete and e.held_of is null)::integer,
         pg_catalog.count(*) filter (where e.held_of is not null)::integer
    from rally100.entries e
    left join rally100.persons p on p.id = e.person_id
   where e.rep_id = p_rep and e.removed_at is null and e.merged_into is null
$$;

create function rally100._confirmed_count(p_person uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select pg_catalog.count(*)::integer from rally100.requirements r
   where r.person_id = p_person and r.confirmed
$$;

/* The Person plus every Person merged into it, however many hops back.
   Notes, messages and history stay on the record they were written to (they
   are append-only); the survivor shows them through its family. */
create function rally100._family(p_person uuid)
returns uuid[]
language sql
stable
security definer
set search_path = ''
as $$
  with recursive f(id) as (
    select p_person
    union
    select p.id from rally100.persons p join f on p.merged_into = f.id)
  select coalesce(pg_catalog.array_agg(f.id), '{}'::pg_catalog.uuid[]) from f
$$;

-- ================================================================= scope ===
/* SCOPE (API.md section 2), resolved from the caller's current profile:
   a rep sees their own entries; a leader or manager every rep whose
   profiles.team_id is theirs; the owner every team. Membership is read live
   from public.profiles, so moving a rep between teams moves who can see them
   without rewriting a single rally100 row. */
create function rally100._rep_in_scope(p_me public.profiles, p_rep uuid)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if p_rep is null then
    return false;
  elsif p_me.role = 'owner' then
    return exists (select 1 from public.profiles where id = p_rep);
  elsif p_me.role in ('leader', 'manager') then
    return exists (select 1 from public.profiles where id = p_rep and team_id = p_me.team_id);
  end if;
  return p_rep = p_me.id;
end $$;

-- A Person is in a leader's scope when a rep in scope has an entry for them.
create function rally100._person_in_scope(p_me public.profiles, p_person uuid)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if p_person is null then
    return false;
  elsif p_me.role = 'owner' then
    return exists (select 1 from rally100.persons where id = p_person);
  elsif p_me.role in ('leader', 'manager') then
    return exists (select 1 from rally100.entries e join public.profiles r on r.id = e.rep_id
                    where e.person_id = p_person and r.team_id = p_me.team_id);
  end if;
  return exists (select 1 from rally100.entries e where e.person_id = p_person and e.rep_id = p_me.id);
end $$;

/* A reward is a leader's when its credited rep is on the leader's team; an
   uncredited referral, when any rep who introduced the Person is (before the
   credit is locked every candidate's leader may see it, afterwards only the
   credited rep's). */
create function rally100._reward_in_scope(p_me public.profiles, p_reward rally100.rewards)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if p_reward.id is null then
    return false;
  elsif p_me.role = 'owner' then
    return true;
  elsif p_reward.rep_id is not null then
    return rally100._rep_in_scope(p_me, p_reward.rep_id);
  elsif p_me.role in ('leader', 'manager') and p_reward.kind = 'referral' then
    return exists (select 1 from rally100.introductions i join public.profiles r on r.id = i.rep_id
                    where i.person_id = p_reward.person_id and r.team_id = p_me.team_id);
  end if;
  return false;
end $$;

-- the live Persons a leader (or the owner) may see
create function rally100._scope_persons(p_me public.profiles)
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select p.id from rally100.persons p
   where p.merged_into is null
     and ((p_me).role = 'owner'
          or exists (select 1 from rally100.entries e join public.profiles r on r.id = e.rep_id
                      where e.person_id = p.id and r.team_id = (p_me).team_id))
$$;

/* Fetch a Person for a leader write: in scope, live, and locked for the rest
   of the transaction so two leaders cannot interleave on one record. Out of
   scope and merged-away both read as not_found. */
create function rally100._person_for_write(p_me public.profiles, p_person uuid)
returns rally100.persons
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_p rally100.persons%rowtype;
begin
  if not rally100._person_in_scope(p_me, p_person) then
    perform rally100._deny('not_found');
  end if;
  select * into v_p from rally100.persons where id = p_person for update;
  if not found or v_p.merged_into is not null then
    perform rally100._deny('not_found');
  end if;
  return v_p;
end $$;

-- ===================================================== normalisation ===
-- The server normalises; the client's own normalisation is a convenience the
-- server never relies on.

-- names: whitespace collapsed (no tabs or newlines inside a name) and trimmed
create function rally100._clean_name(p_raw text)
returns text
language sql
immutable
security definer
set search_path = ''
as $$
  select pg_catalog.btrim(pg_catalog.regexp_replace(coalesce(p_raw, ''), '\s+', ' ', 'g'))
$$;

/* Phone (rule 1): digits only, a leading 1 dropped from 11 digits, stored
   only as exactly ten digits or ''. Anything else that was typed is refused
   rather than stored digits-only, because a stored number that cannot be a
   US phone would light a tile it should not and match duplicates it is not. */
create function rally100._norm_phone(p_raw text)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v pg_catalog.text := pg_catalog.btrim(coalesce(p_raw, ''));
begin
  if v = '' then
    return '';
  end if;
  v := pg_catalog.regexp_replace(v, '[^0-9]', '', 'g');
  if pg_catalog.char_length(v) = 11 and pg_catalog.substr(v, 1, 1) = '1' then
    v := pg_catalog.substr(v, 2);
  end if;
  if v !~ '^[0-9]{10}$' then
    perform rally100._fail('invalid_phone');
  end if;
  return v;
end $$;

-- Handle (rule 1): trimmed, lowercased, a pasted https://host/ prefix and a
-- leading @ removed, anything from the first / ? or # dropped.
create function rally100._norm_handle(p_raw text)
returns text
language sql
immutable
security definer
set search_path = ''
as $$
  select pg_catalog.btrim(
           pg_catalog.regexp_replace(
             pg_catalog.regexp_replace(
               pg_catalog.regexp_replace(pg_catalog.lower(pg_catalog.btrim(coalesce(p_raw, ''))),
                 '^https?://(www\.)?[^/]+/', ''),
               '^@', ''),
             '[/?#].*$', ''))
$$;

create function rally100._norm_tags(p_tags jsonb)
returns text[]
language plpgsql
security definer
set search_path = ''
as $$
declare
  v pg_catalog.text[] := '{}';
  t pg_catalog.jsonb;
begin
  if p_tags is null or pg_catalog.jsonb_typeof(p_tags) = 'null' then
    return v;
  end if;
  if pg_catalog.jsonb_typeof(p_tags) <> 'array' then
    perform rally100._fail('invalid_tag');
  end if;
  for t in select x from pg_catalog.jsonb_array_elements(p_tags) x loop
    if pg_catalog.jsonb_typeof(t) <> 'string' or not ((t #>> '{}') = any (rally100._tags())) then
      perform rally100._fail('invalid_tag');
    end if;
    if not ((t #>> '{}') = any (v)) then
      v := v || (t #>> '{}');
    end if;
  end loop;
  return v;
end $$;

-- free text a person typed: trimmed, length-checked, never interpreted
create function rally100._text(p_raw text, p_max integer)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v pg_catalog.text := pg_catalog.btrim(coalesce(p_raw, ''));
begin
  if pg_catalog.char_length(v) > p_max then
    perform rally100._fail('too_long');
  end if;
  return v;
end $$;

-- ====================================================== entry read model ===

-- What a Draft still needs, as the labels the Sweep shows.
create function rally100._missing(e rally100.entries)
returns jsonb
language sql
immutable
security definer
set search_path = ''
as $$
  select pg_catalog.to_jsonb(pg_catalog.array_remove(array[
    case when e.first_name = '' then 'First name' end,
    case when e.last_name = '' then 'Last name' end,
    case when e.phone = '' then 'Phone' end,
    case when e.handle = '' or e.platform = '' or (e.platform = 'Other' and e.other_app = '')
         then 'Social handle' end
  ]::pg_catalog.text[], null))
$$;

create function rally100._entry_json(e rally100.entries)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select pg_catalog.jsonb_build_object(
    'id', e.id,
    'first_name', e.first_name,
    'last_name', e.last_name,
    'phone', e.phone,
    'handle', e.handle,
    'platform', e.platform,
    'other_app', e.other_app,
    'tags', pg_catalog.to_jsonb(e.tags),
    'notes', e.notes,
    'scene', e.scene,
    'chain_hit', e.chain_hit,
    'is_complete', e.is_complete,
    'counted', e.is_complete and e.removed_at is null and e.held_of is null and e.merged_into is null
               and coalesce((select p.outcome from rally100.persons p where p.id = e.person_id), '')
                   <> 'do_not_contact',
    'held_of', e.held_of,
    'held_of_name', (select pg_catalog.btrim(h.first_name || ' ' || h.last_name)
                       from rally100.entries h where h.id = e.held_of),
    'kept_with', pg_catalog.to_jsonb(e.kept_with),
    'removed', e.removed_at is not null,
    'merged_into', e.merged_into,
    'created_at', e.created_at,
    'completed_at', e.completed_at,
    'missing', rally100._missing(e),
    'person_id', e.person_id,
    'dnc', coalesce((select p.outcome = 'do_not_contact' from rally100.persons p where p.id = e.person_id), false))
$$;

-- every entry of one rep, oldest first; merged-away duplicates are not entries any more
create function rally100._entries_json(p_rep uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(pg_catalog.jsonb_agg(rally100._entry_json(e) order by e.created_at, e.id),
                  '[]'::pg_catalog.jsonb)
    from rally100.entries e
   where e.rep_id = p_rep and e.merged_into is null
$$;

create function rally100._reqs_json(p_person uuid, p_with_note boolean)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select pg_catalog.jsonb_agg(
           pg_catalog.jsonb_build_object(
             'req', g.n,
             'confirmed', coalesce(r.confirmed, false),
             'by_name', case when r.confirmed then rally100._name(r.confirmed_by) end,
             'event_date', case when r.confirmed then r.event_date end)
           || case when p_with_note then pg_catalog.jsonb_build_object('note', coalesce(r.note, ''))
                   else '{}'::pg_catalog.jsonb end
           order by g.n)
    from pg_catalog.generate_series(1, 4) g(n)
    left join rally100.requirements r on r.person_id = p_person and r.req = g.n
$$;

create function rally100._person_json(p_person uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select pg_catalog.jsonb_build_object(
    'id', p.id,
    'first_name', p.first_name,
    'last_name', p.last_name,
    'name', pg_catalog.btrim(p.first_name || ' ' || p.last_name),
    'stage', p.stage,
    'outcome', p.outcome,
    'outcome_date', p.outcome_date,
    'outcome_note', p.outcome_note,
    'interest', p.interest,
    'dnc', p.outcome is not distinct from 'do_not_contact',
    'responsible_leader', p.responsible_leader,
    'responsible_leader_name', case when p.responsible_leader is not null then rally100._name(p.responsible_leader) end,
    'next_action', p.next_action,
    'next_action_owner', p.next_action_owner,
    'next_action_owner_name', case when p.next_action_owner is not null then rally100._name(p.next_action_owner) end,
    'next_action_date', p.next_action_date,
    'meeting_at', p.meeting_at,
    'meeting_how', p.meeting_how,
    'meeting_note', p.meeting_note,
    'start_date', p.start_date,
    'travel_note', p.travel_note,
    'travel_na', p.travel_na,
    'confirmed_count', rally100._confirmed_count(p.id),
    'merged_into', p.merged_into,
    'created_at', p.created_at,
    'updated_at', p.updated_at)
  from rally100.persons p where p.id = p_person
$$;

/* A reward as leaders and the owner see it. A credited rep outside the
   caller's scope is named only as "A rep on another team"; the internal
   reversal reason is the owner's alone. */
create function rally100._reward_json(p_r rally100.rewards, p_me public.profiles)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_vis   boolean;
  v_count integer;
  v_sc    pg_catalog.jsonb;
begin
  if p_r.id is null then
    return null;
  end if;
  v_vis := p_r.rep_id is not null and rally100._rep_in_scope(p_me, p_r.rep_id);
  if p_r.kind = 'list' then
    select c.o_count into v_count from rally100._rep_counts(p_r.rep_id) c;
  end if;
  select pg_catalog.jsonb_build_object('id', s.id, 'by_name', rally100._name(s.leader_id),
                                       'at', s.created_at, 'results', s.results, 'note', s.note)
    into v_sc from rally100.spot_checks s where s.id = p_r.spot_check_id;
  return pg_catalog.jsonb_build_object(
    'id', p_r.id,
    'kind', p_r.kind,
    'status', p_r.status,
    'rep_id', case when v_vis then p_r.rep_id end,
    'rep_name', case when p_r.rep_id is null then null
                     when v_vis then rally100._name(p_r.rep_id)
                     else 'A rep on another team' end,
    'person_id', p_r.person_id,
    'person_name', case when p_r.person_id is not null then rally100._person_name(p_r.person_id) end,
    'incentive_id', p_r.incentive_id,
    'incentive_name', (select i.name from rally100.incentives i where i.id = p_r.incentive_id),
    'amount_cents', p_r.amount_cents,
    'currency', p_r.currency,
    'flags', pg_catalog.to_jsonb(p_r.flags),
    'count', v_count,
    'hold', p_r.kind = 'list' and p_r.status = 'ready' and coalesce(v_count, 0) < 100,
    'spot_checked', p_r.spot_check_id is not null,
    'spot_check', v_sc,
    'approved_by_name', case when p_r.approved_by is not null then rally100._name(p_r.approved_by) end,
    'approved_at', p_r.approved_at,
    'paid_on', p_r.paid_on,
    'paid_method', p_r.paid_method,
    'paid_reference', p_r.paid_reference,
    'paid_by_name', case when p_r.paid_by is not null then rally100._name(p_r.paid_by) end,
    'reversed', p_r.reversed_at is not null,
    'reversed_at', p_r.reversed_at,
    'reversed_reason', case when p_me.role = 'owner' then p_r.reversed_reason end,
    'rep_reason', p_r.rep_reason,
    'correction_note', p_r.correction_note,
    'correction_by_name', case when p_r.correction_by is not null then rally100._name(p_r.correction_by) end,
    'created_at', p_r.created_at,
    'updated_at', p_r.updated_at);
end $$;

-- ======================================================= duplicates ===
/* WITHIN-REP DUPLICATES (rule 4), recomputed for the whole list.

   Walk the rep's live entries oldest first. An entry is HELD when it shares
   a phone, a <platform>:<handle>, or a linked Person with an EARLIER entry
   that is itself not held, unless the rep said the two are "Different
   people" (kept_with); it is held of the earliest such entry. Name-only
   matches never hold.

   Recomputing the whole list from scratch, rather than patching the one
   entry being saved, is what keeps every path consistent: the newer entry is
   held whichever of the pair was saved last, an older draft that gains the
   matching phone holds the newer entry, removing the older releases the
   newer (and restoring it holds the newer again), and a merge of two Persons
   that leaves one rep with two entries on one human holds the newer. The
   result depends only on the entries, never on the order of the saves.

   The Person signal is the third key because "one Person counts once per rep"
   is the owner's rule; it only fires when two of a rep's entries reached the
   same Person by different routes (another rep's identifiers, or a merge). */
create function rally100._dedupe(p_rep uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  r      record;
  v_seen pg_catalog.jsonb := '{}';   -- key -> ids of earlier unheld entries carrying it, oldest first
  v_pos  pg_catalog.jsonb := '{}';   -- unheld entry id -> its position in the walk
  v_keys pg_catalog.text[];
  v_k    pg_catalog.text;
  v_c    pg_catalog.text;
  v_hold pg_catalog.uuid;
  v_best integer;
  v_n    integer := 0;
  v_hkey pg_catalog.text;
begin
  for r in
    select e.id, e.phone, e.platform, e.handle, e.other_app, e.person_id, e.kept_with, e.held_of
      from rally100.entries e
     where e.rep_id = p_rep and e.removed_at is null and e.merged_into is null
     order by e.created_at, e.id
  loop
    v_n := v_n + 1;
    v_hkey := rally100._handle_key(r.platform, r.handle, r.other_app);
    v_keys := pg_catalog.array_remove(array[
                case when r.phone <> '' then 'p:' || r.phone end,
                case when v_hkey is not null then 'h:' || v_hkey end,
                case when r.person_id is not null then 'o:' || r.person_id::pg_catalog.text end
              ]::pg_catalog.text[], null);
    v_hold := null;
    v_best := null;
    foreach v_k in array v_keys loop
      for v_c in
        select x from pg_catalog.jsonb_array_elements_text(coalesce(v_seen -> v_k, '[]'::pg_catalog.jsonb)) x
      loop
        if not (v_c::pg_catalog.uuid = any (r.kept_with)) then
          if v_best is null or (v_pos ->> v_c)::integer < v_best then
            v_best := (v_pos ->> v_c)::integer;
            v_hold := v_c::pg_catalog.uuid;
          end if;
          exit;
        end if;
      end loop;
    end loop;

    if v_hold is null then
      v_pos := v_pos || pg_catalog.jsonb_build_object(r.id::pg_catalog.text, v_n);
      foreach v_k in array v_keys loop
        v_seen := pg_catalog.jsonb_set(v_seen, array[v_k],
                    coalesce(v_seen -> v_k, '[]'::pg_catalog.jsonb) || pg_catalog.to_jsonb(r.id::pg_catalog.text));
      end loop;
    end if;

    if r.held_of is distinct from v_hold then
      update rally100.entries set held_of = v_hold, updated_at = pg_catalog.clock_timestamp()
       where id = r.id;
    end if;
  end loop;
end $$;

-- ========================================================= persons (CRM) ===

-- Every identifier an entry carries is added to its Person; a Person whose
-- first entry was a nameless draft takes its name from the first entry that
-- has one.
create function rally100._add_identifiers(p_entry uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_e    rally100.entries%rowtype;
  v_hkey pg_catalog.text;
begin
  select * into v_e from rally100.entries where id = p_entry;
  if not found or v_e.person_id is null or v_e.removed_at is not null or v_e.merged_into is not null then
    return;
  end if;
  if v_e.phone <> '' then
    insert into rally100.person_identifiers (person_id, kind, value)
    values (v_e.person_id, 'phone', v_e.phone) on conflict do nothing;
  end if;
  v_hkey := rally100._handle_key(v_e.platform, v_e.handle, v_e.other_app);
  if v_hkey is not null then
    insert into rally100.person_identifiers (person_id, kind, value)
    values (v_e.person_id, 'handle', v_hkey) on conflict do nothing;
  end if;
  update rally100.persons
     set first_name = case when first_name = '' then v_e.first_name else first_name end,
         last_name  = case when last_name  = '' then v_e.last_name  else last_name  end,
         updated_at = pg_catalog.clock_timestamp()
   where id = v_e.person_id
     and ((first_name = '' and v_e.first_name <> '') or (last_name = '' and v_e.last_name <> ''));
end $$;

/* LINK AN ENTRY TO A PERSON (rule 6), the first time it carries a phone or a
   handle and is not held. An existing Person is used only on a strong
   signal (same phone, or same <platform>:<handle>) AND a matching last name
   (case-insensitive), or on BOTH strong signals. A strong signal that meets
   a different last name is not enough: a new Person is created and a
   possible_matches row puts the question to a leader. Persons the rep has
   said are someone else ("Different people") are never candidates. */
create function rally100._link(p_entry uuid)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_e       rally100.entries%rowtype;
  v_hkey    pg_catalog.text;
  v_exclude pg_catalog.uuid[];
  v_both    pg_catalog.uuid;
  v_named   pg_catalog.uuid;
  v_person  pg_catalog.uuid;
  v_soft    pg_catalog.jsonb := '[]';
  r         record;
begin
  select * into v_e from rally100.entries where id = p_entry for update;
  if not found or v_e.person_id is not null or v_e.held_of is not null
     or v_e.removed_at is not null or v_e.merged_into is not null then
    return v_e.person_id;
  end if;
  v_hkey := rally100._handle_key(v_e.platform, v_e.handle, v_e.other_app);
  if v_e.phone = '' and v_hkey is null then
    return null;
  end if;

  select coalesce(pg_catalog.array_agg(k.person_id), '{}'::pg_catalog.uuid[]) into v_exclude
    from rally100.entries k
   where k.id = any (v_e.kept_with) and k.person_id is not null;

  for r in
    select c.id, c.last_name, c.by_phone, c.by_handle
      from (select p.id, p.last_name, p.created_at,
                   (v_e.phone <> '' and exists (
                      select 1 from rally100.person_identifiers i
                       where i.person_id = p.id and i.kind = 'phone' and i.value = v_e.phone)) as by_phone,
                   (v_hkey is not null and exists (
                      select 1 from rally100.person_identifiers i
                       where i.person_id = p.id and i.kind = 'handle' and i.value = v_hkey)) as by_handle
              from rally100.persons p
             where p.merged_into is null
               and not (p.id = any (v_exclude))
               and p.id in (select i.person_id from rally100.person_identifiers i
                             where (i.kind = 'phone' and v_e.phone <> '' and i.value = v_e.phone)
                                or (i.kind = 'handle' and i.value = v_hkey))) c
     order by c.created_at, c.id
  loop
    if r.by_phone and r.by_handle then
      v_both := coalesce(v_both, r.id);
    elsif v_e.last_name <> '' and pg_catalog.lower(r.last_name) = pg_catalog.lower(v_e.last_name) then
      v_named := coalesce(v_named, r.id);
    else
      v_soft := v_soft || pg_catalog.jsonb_build_object(
                  'id', r.id, 'signal', case when r.by_phone then 'phone' else 'handle' end);
    end if;
  end loop;

  v_person := coalesce(v_both, v_named);
  if v_person is null then
    insert into rally100.persons (first_name, last_name)
    values (v_e.first_name, v_e.last_name)
    returning id into v_person;
    perform rally100._audit(v_e.rep_id, v_e.team_id, 'person', v_person, 'person_created',
                            pg_catalog.jsonb_build_object('entry_id', v_e.id));
    for r in select (x ->> 'id')::pg_catalog.uuid as id, x ->> 'signal' as signal
               from pg_catalog.jsonb_array_elements(v_soft) x
    loop
      insert into rally100.possible_matches (person_a, person_b, signal)
      values (r.id, v_person, r.signal)
      on conflict do nothing;
    end loop;
  end if;

  update rally100.entries set person_id = v_person, updated_at = pg_catalog.clock_timestamp()
   where id = p_entry;
  return v_person;
end $$;

-- ========================================================= rewards core ===

-- The single referral record for a Person, created In progress if missing.
-- The partial unique index makes the second creation a no-op, not a duplicate.
create function rally100._ensure_referral(p_person uuid, p_team uuid, p_actor uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_rid pg_catalog.uuid;
begin
  insert into rally100.rewards (kind, team_id, person_id, amount_cents, status)
  values ('referral', p_team, p_person, 10000, 'in_progress')
  on conflict (person_id) where kind = 'referral' do nothing
  returning id into v_rid;
  if v_rid is not null then
    perform rally100._reward_event(v_rid, 'create', null, 'in_progress', p_actor, '');
    perform rally100._audit(p_actor, p_team, 'reward', v_rid, 'reward_created',
                            pg_catalog.jsonb_build_object('kind', 'referral', 'person_id', p_person));
  end if;
end $$;

/* RULE 9: WHOEVER SIGNS THE PERSON FIRST. Once all four requirements are
   confirmed, an In progress referral is credited to the rep with the
   EARLIEST recorded_at among this Person's introductions that a leader has
   confirmed received, and moves to Ready for review. recorded_at is server
   time set once when the rep recorded the introduction, so neither the date
   typed on the sheet nor the order in which a leader happened to confirm
   receipt can change who is first. With no received introduction the record
   stays In progress and carries the no_intro flag for the owner. A credit
   the owner set by correct_credit is kept. */
create function rally100._referral_eval(p_person uuid, p_actor uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_r    rally100.rewards%rowtype;
  v_rep  pg_catalog.uuid;
  v_team pg_catalog.uuid;
  v_basis pg_catalog.text;
begin
  select * into v_r from rally100.rewards
   where kind = 'referral' and person_id = p_person for update;
  if not found or v_r.status <> 'in_progress' or v_r.reversed_at is not null then
    return;
  end if;
  if rally100._confirmed_count(p_person) < 4 then
    return;
  end if;

  if v_r.rep_id is not null then
    v_rep := v_r.rep_id;
    v_basis := 'credit set by the owner';
  else
    select i.rep_id, 'first recorded introduction: ' || i.recorded_at::pg_catalog.text
      into v_rep, v_basis
      from rally100.introductions i
     where i.person_id = p_person and i.status = 'introduced'
       and i.recorded_at is not null and i.received_at is not null
     order by i.recorded_at, i.rep_id
     limit 1;
  end if;

  if v_rep is null then
    if not ('no_intro' = any (v_r.flags)) then
      update rally100.rewards set flags = pg_catalog.array_append(flags, 'no_intro'),
                                  updated_at = pg_catalog.clock_timestamp()
       where id = v_r.id;
      perform rally100._reward_event(v_r.id, 'flag_no_intro', 'in_progress', 'in_progress', p_actor,
                                     'all four confirmed, no received introduction');
    end if;
    return;
  end if;

  select team_id into v_team from public.profiles where id = v_rep;
  update rally100.rewards
     set rep_id = v_rep,
         team_id = coalesce(v_team, team_id),
         status = 'ready',
         flags = pg_catalog.array_remove(flags, 'no_intro'),
         updated_at = pg_catalog.clock_timestamp()
   where id = v_r.id;
  perform rally100._reward_event(v_r.id, 'credit', 'in_progress', 'ready', p_actor, v_basis);
  perform rally100._audit(p_actor, v_team, 'reward', v_r.id, 'reward_ready',
                          pg_catalog.jsonb_build_object('rep_id', v_rep, 'basis', v_basis));
end $$;

-- An untick before approval returns the record to In progress and clears the
-- credit, so the rule is applied afresh at the next fourth confirmation.
create function rally100._referral_untick(p_person uuid, p_actor uuid, p_note text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_r rally100.rewards%rowtype;
begin
  select * into v_r from rally100.rewards
   where kind = 'referral' and person_id = p_person for update;
  if not found or v_r.status in ('approved', 'paid') then
    return;
  end if;
  if v_r.status <> 'in_progress' or v_r.rep_id is not null then
    update rally100.rewards set status = 'in_progress', rep_id = null,
                                updated_at = pg_catalog.clock_timestamp()
     where id = v_r.id;
    perform rally100._reward_event(v_r.id, 'untick', v_r.status, 'in_progress', p_actor, p_note);
  end if;
end $$;

-- A reversal is a flag on the record, never a status, and never erases one.
create function rally100._reverse(p_reward uuid, p_actor uuid, p_reason text, p_rep_reason text,
                                  p_action text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_r rally100.rewards%rowtype;
begin
  select * into v_r from rally100.rewards where id = p_reward for update;
  if not found or v_r.reversed_at is not null then
    return;
  end if;
  update rally100.rewards
     set reversed_at = pg_catalog.clock_timestamp(), reversed_by = p_actor,
         reversed_reason = p_reason, rep_reason = coalesce(p_rep_reason, ''),
         updated_at = pg_catalog.clock_timestamp()
   where id = p_reward;
  perform rally100._reward_event(p_reward, p_action, v_r.status, v_r.status, p_actor, p_reason);
end $$;

-- ================================================= settle (count effects) ===
/* After any write that can change a rep's list, put everything that follows
   from the entries in step, in one place, so no path can forget a piece:

     1. (p_dedupe) recompute holds; link newly eligible entries to Persons;
        record identifiers; recompute holds again if a link created a shared
        Person;
     2. contact_completed +10 (and chain_hit +3) for every entry that counts
        for the FIRST time. completed_at is set at that moment and never
        cleared, so an entry earns once in its life: remove-and-restore,
        do-not-contact-and-clear, and blank-then-retype-the-phone all find it
        already set. The key is cc:<phone> (cc:<phone>#<entry id> for the
        newer of a "Different people" pair), so re-adding the same contact
        as a NEW entry finds the key taken and earns nothing either;
        p_quiet names an entry that counts because of a merge: its key is
        recorded at zero points;
     3. scene_cleared, milestones, the reader/full badges and the List
        Completion reward, all keyed so each happens once, ever;
     4. a level-up effect if the XP total crossed a level.

   Returns the effects for the caller to celebrate. */
create function rally100._settle(p_rep uuid, p_entry uuid, p_dedupe boolean, p_quiet uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_eff    pg_catalog.jsonb := '[]';
  v_xp0    integer := rally100._xp_total(p_rep);
  v_xp1    integer;
  v_count  integer;
  v_linked boolean := false;
  v_key    pg_catalog.text;
  v_pts    integer;
  v_rid    pg_catalog.uuid;
  v_team   pg_catalog.uuid;
  r        record;
begin
  if p_dedupe then
    perform rally100._dedupe(p_rep);
    for r in
      select e.id from rally100.entries e
       where e.rep_id = p_rep and e.person_id is null and e.held_of is null
         and e.removed_at is null and e.merged_into is null
         and (e.phone <> '' or rally100._handle_key(e.platform, e.handle, e.other_app) is not null)
       order by e.created_at, e.id
    loop
      perform rally100._link(r.id);
      perform rally100._add_identifiers(r.id);
      v_linked := true;
    end loop;
    if p_entry is not null then
      perform rally100._add_identifiers(p_entry);
    end if;
    if v_linked then
      perform rally100._dedupe(p_rep);
    end if;
  end if;

  for r in
    select e.id, e.phone, e.chain_hit,
           exists (select 1 from rally100.entries k
                    where k.id = any (e.kept_with)
                      and (k.created_at, k.id) < (e.created_at, e.id)) as per_entry
      from rally100.entries e
      left join rally100.persons p on p.id = e.person_id
     where e.rep_id = p_rep and e.completed_at is null and e.is_complete
       and e.removed_at is null and e.held_of is null and e.merged_into is null
       and coalesce(p.outcome, '') <> 'do_not_contact'
     order by e.created_at, e.id
  loop
    update rally100.entries set completed_at = pg_catalog.clock_timestamp()
     where id = r.id and completed_at is null;
    continue when not found;
    v_key := r.phone || case when r.per_entry then '#' || r.id::pg_catalog.text else '' end;
    v_pts := case when r.id is not distinct from p_quiet then 0 else 10 end;
    if rally100._xp(p_rep, 'cc:' || v_key, v_pts,
                    case when v_pts = 0 then 'merge' else 'contact_completed' end) and v_pts > 0 then
      v_eff := v_eff || pg_catalog.jsonb_build_object('type', 'xp', 'points', 10, 'key', 'cc:' || v_key);
      if r.chain_hit and rally100._xp(p_rep, 'ch:' || v_key, 3, 'chain_hit') then
        v_eff := v_eff || pg_catalog.jsonb_build_object('type', 'xp', 'points', 3, 'key', 'ch:' || v_key);
      end if;
    end if;
  end loop;

  select c.o_count into v_count from rally100._rep_counts(p_rep) c;

  for r in
    select s.scene, s.clears_at,
           (select pg_catalog.count(*)
              from rally100.entries e left join rally100.persons p on p.id = e.person_id
             where e.rep_id = p_rep and e.scene = s.scene and e.is_complete and e.removed_at is null
               and e.held_of is null and e.merged_into is null
               and coalesce(p.outcome, '') <> 'do_not_contact') as lit
      from rally100._scenes() s
  loop
    if r.lit >= r.clears_at and rally100._xp(p_rep, 'sc:' || r.scene, 15, 'scene_cleared') then
      v_eff := v_eff || pg_catalog.jsonb_build_object('type', 'scene_cleared', 'scene', r.scene)
                     || pg_catalog.jsonb_build_object('type', 'xp', 'points', 15, 'key', 'sc:' || r.scene);
    end if;
  end loop;

  for r in
    select m.n, m.pts from (values (10, 50), (25, 100), (50, 200), (75, 300), (100, 500)) m(n, pts)
     where m.n <= v_count order by m.n
  loop
    if rally100._xp(p_rep, 'ms:' || r.n, r.pts, 'milestone') then
      v_eff := v_eff || pg_catalog.jsonb_build_object('type', 'milestone', 'n', r.n)
                     || pg_catalog.jsonb_build_object('type', 'xp', 'points', r.pts, 'key', 'ms:' || r.n);
    end if;
  end loop;

  if (select pg_catalog.count(*) from rally100.xp_events x
       where x.rep_id = p_rep and x.key like 'sc:%') >= 3 then
    insert into rally100.badges (rep_id, badge) values (p_rep, 'reader') on conflict do nothing;
  end if;

  /* RULE 8. The first time the count is 100 or more — a jump from 99 to 101
     included — the single List Completion record is created at Ready for
     review. Never again: crossing 100 a second time, or reaching 200, finds
     the record already there (the partial unique index, not this check, is
     what guarantees it). */
  if v_count >= 100 then
    insert into rally100.badges (rep_id, badge) values (p_rep, 'full') on conflict do nothing;
    select coalesce(pr.team_id,
                    (select e.team_id from rally100.entries e where e.rep_id = p_rep
                      order by e.created_at desc limit 1))
      into v_team from public.profiles pr where pr.id = p_rep;
    v_rid := null;
    insert into rally100.rewards (kind, team_id, rep_id, amount_cents, status)
    values ('list', v_team, p_rep, 10000, 'ready')
    on conflict (rep_id) where kind = 'list' do nothing
    returning id into v_rid;
    if v_rid is not null then
      perform rally100._reward_event(v_rid, 'create', null, 'ready', null,
                                     'count reached ' || v_count::pg_catalog.text);
      perform rally100._audit(null, v_team, 'reward', v_rid, 'reward_created',
                              pg_catalog.jsonb_build_object('kind', 'list', 'rep_id', p_rep, 'count', v_count));
      v_eff := v_eff || pg_catalog.jsonb_build_object('type', 'list_ready');
    end if;
  end if;

  v_xp1 := rally100._xp_total(p_rep);
  if (rally100._level(v_xp1) ->> 'name') is distinct from (rally100._level(v_xp0) ->> 'name') then
    v_eff := v_eff || pg_catalog.jsonb_build_object('type', 'level', 'name', rally100._level(v_xp1) ->> 'name');
  end if;
  return v_eff;
end $$;

-- Count-driven effects for every rep who has an entry on this Person: a
-- do_not_contact cleared, or two Persons merged, can move several counts.
create function rally100._settle_person_reps(p_person uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  r record;
begin
  for r in
    select distinct e.rep_id from rally100.entries e
     where e.person_id = any (rally100._family(p_person)) and e.merged_into is null
     order by e.rep_id
  loop
    perform rally100._settle(r.rep_id, null, false, null);
  end loop;
end $$;

-- `{type:'held', ...}` when this save left the entry newly held
create function rally100._held_effect(p_entry uuid, p_before uuid, p_new boolean)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_e rally100.entries%rowtype;
  v_o rally100.entries%rowtype;
begin
  select * into v_e from rally100.entries where id = p_entry;
  if not found or v_e.held_of is null or (not p_new and p_before is not distinct from v_e.held_of) then
    return null;
  end if;
  select * into v_o from rally100.entries where id = v_e.held_of;
  return pg_catalog.jsonb_build_object(
    'type', 'held',
    'older_id', v_o.id,
    'older_name', pg_catalog.btrim(v_o.first_name || ' ' || v_o.last_name),
    'by', case when v_e.phone <> '' and v_e.phone = v_o.phone then 'phone'
               when rally100._handle_key(v_e.platform, v_e.handle, v_e.other_app)
                    = rally100._handle_key(v_o.platform, v_o.handle, v_o.other_app) then 'handle'
               else 'person' end);
end $$;

-- the answer every list write returns
create function rally100._save_shape(p_rep uuid, p_entry uuid, p_effects jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_c  record;
  v_xp integer;
begin
  select * into v_c from rally100._rep_counts(p_rep);
  v_xp := rally100._xp_total(p_rep);
  return pg_catalog.jsonb_build_object(
    'entry', (select rally100._entry_json(e) from rally100.entries e where e.id = p_entry),
    'effects', coalesce(p_effects, '[]'::pg_catalog.jsonb),
    'count', v_c.o_count,
    'drafts', v_c.o_drafts,
    'held', v_c.o_held,
    'xp', v_xp,
    'level', rally100._level(v_xp));
end $$;

-- ================================================== rep-facing read models ===

/* A rep's view of one entry's recruiting progress. Before this rep has
   recorded their OWN introduction they see Added (or Introduction planned)
   whatever the true stage, no requirement block and no leader decisions:
   another rep's introduction of the same Person is never visible to them.
   Nothing here names another rep. */
create function rally100._intro_obj(p_entry uuid, p_rep uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_e      rally100.entries%rowtype;
  v_p      rally100.persons%rowtype;
  v_i      rally100.introductions%rowtype;
  v_has_i  boolean;
  v_own    boolean;
  v_team   pg_catalog.uuid;
  v_leader pg_catalog.uuid;
  v_ix     integer;
  v_next1  integer;
  v_who    pg_catalog.text;
  v_wname  pg_catalog.text;
  v_text   pg_catalog.text;
  v_owner_role pg_catalog.text;
begin
  select * into v_e from rally100.entries where id = p_entry and rep_id = p_rep;
  if not found or v_e.person_id is null then
    return null;
  end if;
  select * into v_p from rally100.persons where id = v_e.person_id;
  select * into v_i from rally100.introductions where person_id = v_e.person_id and rep_id = p_rep;
  v_has_i := found;
  v_own := v_has_i and v_i.status = 'introduced';
  select team_id into v_team from public.profiles where id = p_rep;
  v_leader := coalesce(v_p.responsible_leader, rally100._team_leader(v_team));
  v_ix := rally100._stage_ix(v_p.stage);

  if v_p.outcome = 'do_not_contact' then
    v_who := 'leader'; v_text := 'nothing needed from you';
  elsif not v_own then
    v_who := 'you';
    v_text := case when v_has_i then 'make the introduction' else 'introduce them' end;
  elsif v_p.next_action <> '' and (v_p.next_action_owner is null or v_p.next_action_owner = p_rep
        or exists (select 1 from public.profiles o where o.id = v_p.next_action_owner
                    and o.role in ('leader', 'manager', 'owner'))) then
    if v_p.next_action_owner = p_rep then
      v_who := 'you';
    else
      v_who := 'leader';
      v_leader := coalesce(v_p.next_action_owner, v_leader);
    end if;
    v_text := v_p.next_action;
  elsif v_p.outcome = 'follow_up' then
    v_who := case when v_ix <= rally100._stage_ix('introduced') then 'you' else 'leader' end;
    v_text := 'follow up';
  elsif v_p.outcome = 'not_interested' then
    v_who := 'leader'; v_text := 'nothing needed from you';
  elsif v_ix <= rally100._stage_ix('introduced') then
    v_who := 'leader'; v_text := 'schedules the meeting';
  elsif v_p.stage = 'meeting_scheduled' then
    v_who := 'leader'; v_text := 'holds the meeting';
  else
    select pg_catalog.min(g.n) into v_next1
      from pg_catalog.generate_series(1, 4) g(n)
     where not exists (select 1 from rally100.requirements q
                        where q.person_id = v_p.id and q.req = g.n and q.confirmed);
    v_who := 'leader';
    v_text := case v_next1
                when 1 then 'confirms the meeting'
                when 2 then 'confirms the commitment'
                when 3 then 'confirms the agreement'
                when 4 then 'confirms start date and travel plans'
                else case when v_p.stage = 'arrived' then 'nothing needed from you'
                          else 'reviews the referral reward' end
              end;
  end if;
  v_wname := case when v_who = 'you' then rally100._name(p_rep)
                  when v_leader is not null then rally100._name(v_leader) end;

  return pg_catalog.jsonb_build_object(
    'entry_id', v_e.id,
    'person_id', v_e.person_id,
    'name', pg_catalog.btrim(v_e.first_name || ' ' || v_e.last_name),
    'status', case when v_has_i then v_i.status end,
    'recorded_at', case when v_has_i then v_i.recorded_at end,
    'received', v_has_i and v_i.received_at is not null,
    'stage', case when v_own then v_p.stage
                  when v_has_i then 'intro_planned' else 'added' end,
    'outcome', case when v_own then v_p.outcome
                    when v_p.outcome = 'do_not_contact' then v_p.outcome
                    when v_p.outcome = 'follow_up' and v_ix <= rally100._stage_ix('introduced') then v_p.outcome
                    end,
    'outcome_date', case when v_own or v_p.outcome = 'do_not_contact'
                              or (v_p.outcome = 'follow_up' and v_ix <= rally100._stage_ix('introduced'))
                         then v_p.outcome_date end,
    'interest', case when v_own then v_p.interest else 'unknown' end,
    'requirements', case when v_own then rally100._reqs_json(v_p.id, false) end,
    'next', pg_catalog.jsonb_build_object('who', v_who, 'name', v_wname, 'text', v_text),
    'meeting_at', case when v_own then v_p.meeting_at end,
    'leader_name', case when v_leader is not null then rally100._name(v_leader) end);
end $$;

-- the List Completion reward as the rep sees it; the internal reason never leaves
create function rally100._list_reward_rep(p_rep uuid, p_count integer)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select pg_catalog.jsonb_build_object(
    'status', r.status,
    'hold', r.status = 'ready' and p_count < 100,
    'amount_cents', r.amount_cents,
    'approved_at', r.approved_at,
    'paid_on', r.paid_on,
    'reversed', r.reversed_at is not null,
    'rep_reason', case when r.reversed_at is not null then coalesce(r.rep_reason, '') end)
    from rally100.rewards r
   where r.kind = 'list' and r.rep_id = p_rep
$$;

/* One row per Person this rep recorded an introduction of. When the record is
   credited to another rep this rep learns only that, and the name THEY typed:
   never who, never when, never how far the Person went. */
create function rally100._referrals_rep(p_rep uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(pg_catalog.jsonb_agg(x.obj order by x.recorded_at, x.person_id), '[]'::pg_catalog.jsonb)
    from (
      select i.person_id, i.recorded_at,
             case
               when r.rep_id is not null and r.rep_id <> p_rep then
                 pg_catalog.jsonb_build_object('credited', 'other', 'name', n.name)
               else pg_catalog.jsonb_build_object(
                 'person_id', i.person_id,
                 'name', n.name,
                 'status', r.status,
                 'credited', case when r.rep_id = p_rep then 'me' end,
                 'confirmed_count', rally100._confirmed_count(i.person_id),
                 'requirements', rally100._reqs_json(i.person_id, false),
                 'approved_at', r.approved_at,
                 'paid_on', r.paid_on,
                 'reversed', r.reversed_at is not null,
                 'rep_reason', case when r.reversed_at is not null then coalesce(r.rep_reason, '') end)
             end as obj
        from rally100.introductions i
        left join rally100.rewards r on r.kind = 'referral' and r.person_id = i.person_id
        cross join lateral (
          select coalesce(
                   (select pg_catalog.btrim(e.first_name || ' ' || e.last_name) from rally100.entries e
                     where e.rep_id = p_rep and e.person_id = i.person_id and e.merged_into is null
                     order by (e.removed_at is not null), e.created_at limit 1),
                   (select pg_catalog.btrim(e.first_name || ' ' || e.last_name) from rally100.entries e
                     where e.id = i.entry_id),
                   '') as name) n
       where i.rep_id = p_rep and i.status = 'introduced') x
$$;

-- one intro card per live, unheld entry with an introduction or a Person past Added
create function rally100._intros_rep(p_rep uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(pg_catalog.jsonb_agg(rally100._intro_obj(e.id, p_rep) order by e.created_at, e.id),
                  '[]'::pg_catalog.jsonb)
    from rally100.entries e
    join rally100.persons p on p.id = e.person_id
   where e.rep_id = p_rep and e.removed_at is null and e.merged_into is null and e.held_of is null
     and (p.stage <> 'added'
          or exists (select 1 from rally100.introductions i where i.person_id = e.person_id and i.rep_id = p_rep))
$$;

create function rally100._scenes_json(p_rep uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select pg_catalog.jsonb_object_agg(s.scene, pg_catalog.jsonb_build_object(
           'names', (select pg_catalog.count(*) from rally100.entries e
                      where e.rep_id = p_rep and e.scene = s.scene and e.removed_at is null and e.merged_into is null),
           'lit', (select pg_catalog.count(*) from rally100.entries e left join rally100.persons p on p.id = e.person_id
                    where e.rep_id = p_rep and e.scene = s.scene and e.is_complete and e.removed_at is null
                      and e.held_of is null and e.merged_into is null and coalesce(p.outcome, '') <> 'do_not_contact'),
           'drafts', (select pg_catalog.count(*) from rally100.entries e
                       where e.rep_id = p_rep and e.scene = s.scene and not e.is_complete and e.removed_at is null
                         and e.held_of is null and e.merged_into is null),
           'cleared', exists (select 1 from rally100.xp_events x where x.rep_id = p_rep and x.key = 'sc:' || s.scene)))
    from rally100._scenes() s
$$;

create function rally100._incentive_json(p_incentive uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select pg_catalog.jsonb_build_object(
    'id', i.id, 'name', i.name, 'pictures', i.pictures, 'prize_cents', i.prize_cents,
    'how_to_earn', i.how_to_earn, 'status', i.status, 'created_at', i.created_at, 'updated_at', i.updated_at)
    from rally100.incentives i where i.id = p_incentive
$$;

-- ================================================ leader read models ===

create function rally100._q(p_person uuid, p_me public.profiles)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select pg_catalog.jsonb_build_object(
    'person_id', p.id,
    'name', pg_catalog.btrim(p.first_name || ' ' || p.last_name),
    'stage', p.stage,
    'outcome', p.outcome,
    'outcome_date', p.outcome_date,
    'meeting_at', p.meeting_at,
    'reps', (select coalesce(pg_catalog.jsonb_agg(distinct rally100._name(e.rep_id)), '[]'::pg_catalog.jsonb)
               from rally100.entries e
              where e.person_id = p.id and e.merged_into is null and rally100._rep_in_scope(p_me, e.rep_id)),
    'next_action', p.next_action,
    'confirmed_count', rally100._confirmed_count(p.id),
    'updated_at', p.updated_at)
    from rally100.persons p where p.id = p_person
$$;

create function rally100._queues(p_me public.profiles)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_owner boolean := p_me.role = 'owner';
  v_scope pg_catalog.uuid[];
  v_new   pg_catalog.jsonb;
  v_meet  pg_catalog.jsonb;
  v_fu    pg_catalog.jsonb;
  v_conf  pg_catalog.jsonb;
  v_rev   pg_catalog.jsonb;
  v_msg   pg_catalog.jsonb;
  v_pm    pg_catalog.jsonb;
begin
  select coalesce(pg_catalog.array_agg(x), '{}'::pg_catalog.uuid[]) into v_scope
    from rally100._scope_persons(p_me) x;

  -- introductions recorded by a rep in scope and not yet received
  select coalesce(pg_catalog.jsonb_agg(rally100._q(s.id, p_me) order by s.first_rec, s.id), '[]'::pg_catalog.jsonb)
    into v_new
    from (select p.id,
                 (select pg_catalog.min(i.recorded_at) from rally100.introductions i
                   where i.person_id = p.id and i.status = 'introduced' and i.received_at is null
                     and rally100._rep_in_scope(p_me, i.rep_id)) as first_rec
            from rally100.persons p
           where p.id = any (v_scope) and p.outcome is null) s
   where s.first_rec is not null;

  select coalesce(pg_catalog.jsonb_agg(rally100._q(p.id, p_me) order by p.meeting_at nulls last, p.id), '[]'::pg_catalog.jsonb)
    into v_meet
    from rally100.persons p
   where p.id = any (v_scope) and p.stage = 'meeting_scheduled' and p.outcome is null;

  select coalesce(pg_catalog.jsonb_agg(rally100._q(p.id, p_me) order by p.outcome_date, p.id), '[]'::pg_catalog.jsonb)
    into v_fu
    from rally100.persons p
   where p.id = any (v_scope) and p.outcome = 'follow_up' and p.outcome_date <= rally100._today();

  select coalesce(pg_catalog.jsonb_agg(rally100._q(p.id, p_me) order by p.updated_at, p.id), '[]'::pg_catalog.jsonb)
    into v_conf
    from rally100.persons p
   where p.id = any (v_scope) and p.outcome is null
     and rally100._stage_ix(p.stage) >= rally100._stage_ix('meeting_completed')
     and rally100._confirmed_count(p.id) < 4;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
           'reward_id', r.id, 'kind', r.kind, 'status', r.status, 'rep_id', r.rep_id,
           'rep_name', rally100._name(r.rep_id), 'person_id', r.person_id,
           'person_name', case when r.person_id is not null then rally100._person_name(r.person_id) end,
           'amount_cents', r.amount_cents,
           'hold', r.kind = 'list' and r.status = 'ready'
                   and (select c.o_count from rally100._rep_counts(r.rep_id) c) < 100,
           'spot_checked', r.spot_check_id is not null,
           'flags', pg_catalog.to_jsonb(r.flags)) order by r.created_at, r.id), '[]'::pg_catalog.jsonb)
    into v_rev
    from rally100.rewards r
   where r.status in ('ready', 'needs_correction') and r.reversed_at is null and r.rep_id is not null
     and (v_owner or rally100._rep_in_scope(p_me, r.rep_id));

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
           'id', m.id, 'person_id', m.person_id, 'person_name', rally100._person_name(m.person_id),
           'rep_name', rally100._name(m.rep_id), 'body', m.body, 'created_at', m.created_at)
           order by m.created_at, m.id), '[]'::pg_catalog.jsonb)
    into v_msg
    from rally100.messages m
   where m.read_at is null and (v_owner or rally100._rep_in_scope(p_me, m.rep_id));

  /* A leader sees a possible match only when BOTH Persons are in their
     scope: a match is a question about two records, and a Person known only
     to another team's rep is not this leader's to see or to merge. The
     owner sees them all. */
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
           'id', pm.id,
           'a', pg_catalog.jsonb_build_object('id', a.id, 'name', pg_catalog.btrim(a.first_name || ' ' || a.last_name)),
           'b', pg_catalog.jsonb_build_object('id', b.id, 'name', pg_catalog.btrim(b.first_name || ' ' || b.last_name)),
           'signal', pm.signal) order by pm.created_at, pm.id), '[]'::pg_catalog.jsonb)
    into v_pm
    from rally100.possible_matches pm
    join rally100.persons a on a.id = pm.person_a
    join rally100.persons b on b.id = pm.person_b
   where pm.status = 'open' and a.merged_into is null and b.merged_into is null
     and (v_owner or (a.id = any (v_scope) and b.id = any (v_scope)));

  return pg_catalog.jsonb_build_object(
    'new_intros', v_new, 'meetings', v_meet, 'follow_ups', v_fu, 'confirmations', v_conf,
    'reviews', v_rev, 'messages', v_msg, 'matches', v_pm);
end $$;

-- one rep's line on the leader and owner screens
create function rally100._rep_row(p_uid uuid, p_with_team boolean)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select pg_catalog.jsonb_build_object(
    'id', p.id,
    'name', rally100._name(p.id),
    'email', p.email,
    'role', p.role,
    'disabled', p.disabled,
    'count', c.o_count,
    'drafts', c.o_drafts,
    'held', c.o_held,
    'last_activity', (select pg_catalog.max(a.created_at) from rally100.audit a where a.actor = p.id),
    'list_reward', (select pg_catalog.jsonb_build_object(
                             'id', r.id, 'status', r.status,
                             'hold', r.status = 'ready' and c.o_count < 100,
                             'spot_checked', r.spot_check_id is not null,
                             'reversed', r.reversed_at is not null)
                      from rally100.rewards r where r.kind = 'list' and r.rep_id = p.id),
    'intros_received', (select pg_catalog.count(*) from rally100.introductions i
                         where i.rep_id = p.id and i.received_at is not null),
    'signed', (select pg_catalog.count(*) from rally100.rewards r
                where r.kind = 'referral' and r.rep_id = p.id and r.reversed_at is null))
    || case when p_with_team
            then pg_catalog.jsonb_build_object('team_id', p.team_id,
                   'team_name', (select t.name from public.teams t where t.id = p.team_id))
            else '{}'::pg_catalog.jsonb end
    from public.profiles p
    cross join lateral rally100._rep_counts(p.id) c
   where p.id = p_uid
$$;

-- ==================================================== incentive pictures ===
/* Pictures arrive inline as data:image/jpeg;base64 strings because v1 has no
   file storage: at most four, each at most 400,000 characters, JPEG only.
   Raster only on purpose — an SVG "image" can carry script. */
create function rally100._check_pictures(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v pg_catalog.jsonb;
begin
  if p is null or pg_catalog.jsonb_typeof(p) = 'null' then
    return '[]'::pg_catalog.jsonb;
  end if;
  if pg_catalog.jsonb_typeof(p) <> 'array' then
    perform rally100._fail('invalid_picture');
  end if;
  if pg_catalog.jsonb_array_length(p) > 4 then
    perform rally100._fail('too_many_pictures');
  end if;
  for v in select x from pg_catalog.jsonb_array_elements(p) x loop
    if pg_catalog.jsonb_typeof(v) <> 'string' then
      perform rally100._fail('invalid_picture');
    end if;
    if pg_catalog.char_length(v #>> '{}') > 400000 then
      perform rally100._fail('picture_too_large');
    end if;
    if (v #>> '{}') !~ '^data:image/jpeg;base64,[A-Za-z0-9+/]+={0,2}$' then
      perform rally100._fail('invalid_picture');
    end if;
  end loop;
  return p;
end $$;

-- =================================================================== API ===
-- ------------------------------------------------------------ 6.1 everyone

/* whoami answers a signed-in account with no team instead of refusing it, so
   the app can explain placement ("ask your leader to add you"). A disabled
   account is still refused: it must learn it is disabled, not see a home. */
create function rally100.whoami()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid  pg_catalog.uuid := auth.uid();
  v_me   public.profiles;
  v_user pg_catalog.jsonb;
begin
  if v_uid is null then
    raise exception 'rally100: not signed in' using errcode = '42501';
  end if;
  select * into v_me from public.profiles where id = v_uid;
  if not found then
    raise exception 'rally100: not signed in' using errcode = '42501';
  end if;
  if v_me.disabled then
    raise exception 'rally100: disabled' using errcode = '42501';
  end if;
  v_user := pg_catalog.jsonb_build_object(
    'id', v_me.id, 'name', rally100._name(v_me.id), 'email', v_me.email, 'role', v_me.role,
    'team_id', v_me.team_id,
    'team_name', (select t.name from public.teams t where t.id = v_me.team_id));
  if v_me.team_id is null then
    return pg_catalog.jsonb_build_object('user', v_user, 'no_team', true);
  end if;
  return pg_catalog.jsonb_build_object(
    'user', v_user,
    'ack_version_required', 1,
    'ack_accepted', exists (select 1 from rally100.acks a where a.rep_id = v_me.id and a.version = 1));
end $$;

create function rally100.accept_ack(p_version integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me public.profiles := rally100._caller();
begin
  if p_version is distinct from 1 then
    perform rally100._fail('invalid_version');
  end if;
  insert into rally100.acks (rep_id, version) values (v_me.id, p_version) on conflict do nothing;
  if found then
    perform rally100._audit(v_me.id, v_me.team_id, 'ack', v_me.id, 'ack_accepted',
                            pg_catalog.jsonb_build_object('version', p_version));
  end if;
  return pg_catalog.jsonb_build_object('ok', true);
end $$;

-- ---------------------------------------------------------------- 6.2 rep

create function rally100.rep_state()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_me public.profiles := rally100._caller();
  v_c  record;
  v_xp integer;
  v_ld pg_catalog.uuid;
begin
  select * into v_c from rally100._rep_counts(v_me.id);
  v_xp := rally100._xp_total(v_me.id);
  v_ld := rally100._team_leader(v_me.team_id);
  return pg_catalog.jsonb_build_object(
    'count', v_c.o_count,
    'drafts', v_c.o_drafts,
    'held', v_c.o_held,
    'xp', v_xp,
    'level', rally100._level(v_xp),
    'milestones', (select coalesce(pg_catalog.jsonb_agg(m.n order by m.n), '[]'::pg_catalog.jsonb)
                     from (select pg_catalog.substr(x.key, 4)::integer as n from rally100.xp_events x
                            where x.rep_id = v_me.id and x.key like 'ms:%') m),
    'badges', (select coalesce(pg_catalog.jsonb_agg(b.badge order by b.created_at, b.badge), '[]'::pg_catalog.jsonb)
                 from rally100.badges b where b.rep_id = v_me.id),
    'scenes', rally100._scenes_json(v_me.id),
    'entries', rally100._entries_json(v_me.id),
    'list_reward', rally100._list_reward_rep(v_me.id, v_c.o_count),
    'referrals', rally100._referrals_rep(v_me.id),
    'intros', rally100._intros_rep(v_me.id),
    'incentives', (select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                            'id', i.id, 'name', i.name, 'pictures', i.pictures,
                            'prize_cents', i.prize_cents, 'how_to_earn', i.how_to_earn)
                            order by i.created_at, i.id), '[]'::pg_catalog.jsonb)
                     from rally100.incentives i where i.status = 'published'),
    'awards', (select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                        'id', r.id, 'incentive_id', r.incentive_id,
                        'name', (select i.name from rally100.incentives i where i.id = r.incentive_id),
                        'amount_cents', r.amount_cents, 'status', r.status, 'paid_on', r.paid_on,
                        'reversed', r.reversed_at is not null,
                        'rep_reason', case when r.reversed_at is not null then coalesce(r.rep_reason, '') end)
                        order by r.created_at, r.id), '[]'::pg_catalog.jsonb)
                 from rally100.rewards r where r.kind = 'incentive' and r.rep_id = v_me.id),
    'leader', case when v_ld is not null then pg_catalog.jsonb_build_object('name', rally100._name(v_ld)) end);
end $$;

/* Create or update one List Entry by its client-generated id.

   An id that exists but belongs to another rep is answered exactly like an
   id this rep may not touch for any other reason — not_found — and nothing
   is written. A key that is ABSENT leaves its field alone, so an outbox that
   folds an old save into a newer one cannot blank a field the rep never
   touched. scene and chain_hit describe how the name was FIRST added; they
   are taken on create and ignored afterwards, so a rep cannot walk counted
   names from Scene to Scene clearing each one for XP. */
create function rally100.save_entry(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me       public.profiles := rally100._caller();
  v_id       pg_catalog.uuid;
  v_old      rally100.entries%rowtype;
  v_new      boolean;
  v_first    pg_catalog.text;
  v_last     pg_catalog.text;
  v_phone    pg_catalog.text;
  v_handle   pg_catalog.text;
  v_platform pg_catalog.text;
  v_other    pg_catalog.text;
  v_tags     pg_catalog.text[];
  v_notes    pg_catalog.text;
  v_scene    pg_catalog.text;
  v_chain    boolean;
  v_changed  pg_catalog.text[] := '{}';
  v_eff      pg_catalog.jsonb;
  v_held     pg_catalog.jsonb;
begin
  if p is null or pg_catalog.jsonb_typeof(p) <> 'object' then
    perform rally100._fail('invalid_payload');
  end if;
  if coalesce(p ->> 'id', '') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
    perform rally100._fail('invalid_id');
  end if;
  v_id := (p ->> 'id')::pg_catalog.uuid;

  perform rally100._lock_rep(v_me.id);
  select * into v_old from rally100.entries where id = v_id for update;
  v_new := not found;
  if not v_new then
    if v_old.rep_id <> v_me.id then
      perform rally100._deny('not_found');
    end if;
    if v_old.removed_at is not null or v_old.merged_into is not null then
      perform rally100._fail('entry_removed');
    end if;
  end if;

  v_first := case when p ? 'first_name' then rally100._clean_name(p ->> 'first_name')
                  else coalesce(v_old.first_name, '') end;
  if v_first = '' then
    perform rally100._fail('first_required');
  end if;
  v_last := case when p ? 'last_name' then rally100._clean_name(p ->> 'last_name')
                 else coalesce(v_old.last_name, '') end;
  if pg_catalog.char_length(v_first) > 60 or pg_catalog.char_length(v_last) > 60 then
    perform rally100._fail('name_too_long');
  end if;
  v_phone := case when p ? 'phone' then rally100._norm_phone(p ->> 'phone')
                  else coalesce(v_old.phone, '') end;
  v_handle := case when p ? 'handle' then rally100._norm_handle(p ->> 'handle')
                   else coalesce(v_old.handle, '') end;
  if pg_catalog.char_length(v_handle) > 100 then
    perform rally100._fail('too_long');
  end if;
  v_platform := case when p ? 'platform' then coalesce(pg_catalog.btrim(p ->> 'platform'), '')
                     else coalesce(v_old.platform, '') end;
  if v_platform not in ('', 'Instagram', 'Snapchat', 'TikTok', 'Facebook', 'X', 'LinkedIn', 'Discord', 'Other') then
    perform rally100._fail('invalid_platform');
  end if;
  v_other := case when p ? 'other_app' then rally100._clean_name(p ->> 'other_app')
                  else coalesce(v_old.other_app, '') end;
  if v_platform <> 'Other' then
    v_other := '';
  end if;
  if pg_catalog.char_length(v_other) > 40 then
    perform rally100._fail('too_long');
  end if;
  if v_handle <> '' and v_platform = '' then
    perform rally100._fail('platform_required');
  end if;
  if v_platform = 'Other' and v_other = '' then
    perform rally100._fail('other_app_required');
  end if;
  v_notes := case when p ? 'notes' then coalesce(p ->> 'notes', '') else coalesce(v_old.notes, '') end;
  if pg_catalog.char_length(v_notes) > 2000 then
    perform rally100._fail('too_long');
  end if;
  v_tags := case when p ? 'tags' then rally100._norm_tags(p -> 'tags')
                 else coalesce(v_old.tags, '{}'::pg_catalog.text[]) end;

  if v_new then
    v_scene := nullif(pg_catalog.btrim(coalesce(p ->> 'scene', '')), '');
    if v_scene is not null and not exists (select 1 from rally100._scenes() s where s.scene = v_scene) then
      perform rally100._fail('invalid_scene');
    end if;
    v_chain := coalesce((p ->> 'chain_hit') = 'true', false);
    insert into rally100.entries (id, team_id, rep_id, first_name, last_name, phone, handle, platform,
                                  other_app, tags, notes, scene, chain_hit)
    values (v_id, v_me.team_id, v_me.id, v_first, v_last, v_phone, v_handle, v_platform,
            v_other, v_tags, v_notes, v_scene, v_chain);
    perform rally100._audit(v_me.id, v_me.team_id, 'entry', v_id, 'entry_created',
                            pg_catalog.jsonb_build_object('scene', v_scene, 'chain_hit', v_chain));
  else
    if v_first    is distinct from v_old.first_name then v_changed := v_changed || 'first_name'::pg_catalog.text; end if;
    if v_last     is distinct from v_old.last_name  then v_changed := v_changed || 'last_name'::pg_catalog.text;  end if;
    if v_phone    is distinct from v_old.phone      then v_changed := v_changed || 'phone'::pg_catalog.text;      end if;
    if v_handle   is distinct from v_old.handle     then v_changed := v_changed || 'handle'::pg_catalog.text;     end if;
    if v_platform is distinct from v_old.platform   then v_changed := v_changed || 'platform'::pg_catalog.text;   end if;
    if v_other    is distinct from v_old.other_app  then v_changed := v_changed || 'other_app'::pg_catalog.text;  end if;
    if v_tags     is distinct from v_old.tags       then v_changed := v_changed || 'tags'::pg_catalog.text;       end if;
    if v_notes    is distinct from v_old.notes      then v_changed := v_changed || 'notes'::pg_catalog.text;      end if;
    if pg_catalog.cardinality(v_changed) > 0 then
      update rally100.entries
         set first_name = v_first, last_name = v_last, phone = v_phone, handle = v_handle,
             platform = v_platform, other_app = v_other, tags = v_tags, notes = v_notes,
             updated_at = pg_catalog.clock_timestamp()
       where id = v_id;
      perform rally100._audit(v_me.id, v_me.team_id, 'entry', v_id, 'entry_updated',
                              pg_catalog.jsonb_build_object('changed', pg_catalog.to_jsonb(v_changed)));
    end if;
  end if;

  v_eff := rally100._settle(v_me.id, v_id, true, null);
  v_held := rally100._held_effect(v_id, v_old.held_of, v_new);
  if v_held is not null then
    v_eff := pg_catalog.jsonb_build_array(v_held) || v_eff;
  end if;
  return rally100._save_shape(v_me.id, v_id, v_eff);
end $$;

/* RULE 5. p_entry is the HELD (newer) entry.
   same: the older entry takes every field it is missing from the newer one,
     tags are united and notes appended; the newer is removed with
     merged_into. The merge earns nothing: if the older now counts for the
     first time its completion key is recorded at zero points.
   different: only for a same-phone match — one handle cannot belong to two
     humans, so a handle match is fixed or merged, never kept — and only with
     a reason. Both entries record each other in kept_with and both count;
     the newer's XP key becomes per-entry and it gets its own Person. */
create function rally100.resolve_duplicate(p_entry uuid, p_decision text, p_reason text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me     public.profiles := rally100._caller();
  v_x      rally100.entries%rowtype;
  v_o      rally100.entries%rowtype;
  v_reason pg_catalog.text;
  v_eff    pg_catalog.jsonb;
  v_held   pg_catalog.jsonb;
  v_hx     pg_catalog.text;
  v_ho     pg_catalog.text;
begin
  perform rally100._lock_rep(v_me.id);
  select * into v_x from rally100.entries where id = p_entry for update;
  if not found or v_x.rep_id <> v_me.id or v_x.merged_into is not null then
    perform rally100._deny('not_found');
  end if;
  if v_x.removed_at is not null then
    perform rally100._fail('entry_removed');
  end if;
  if p_decision is null or p_decision not in ('same', 'different') then
    perform rally100._fail('invalid_decision');
  end if;
  if v_x.held_of is null then
    perform rally100._fail('not_held');
  end if;
  select * into v_o from rally100.entries where id = v_x.held_of for update;

  if p_decision = 'same' then
    update rally100.entries o
       set first_name = case when o.first_name = '' then v_x.first_name else o.first_name end,
           last_name  = case when o.last_name  = '' then v_x.last_name  else o.last_name  end,
           phone      = case when o.phone      = '' then v_x.phone      else o.phone      end,
           handle     = case when o.handle     = '' then v_x.handle     else o.handle     end,
           platform   = case when o.handle     = '' then v_x.platform   else o.platform   end,
           other_app  = case when o.handle     = '' then v_x.other_app  else o.other_app  end,
           tags       = o.tags || coalesce(array(select t from pg_catalog.unnest(v_x.tags) t
                                                  where not (t = any (o.tags))), '{}'::pg_catalog.text[]),
           notes      = case when v_x.notes = '' then o.notes
                             when o.notes = '' then v_x.notes
                             else o.notes || E'\n\n' || v_x.notes end,
           person_id  = coalesce(o.person_id, v_x.person_id),
           updated_at = pg_catalog.clock_timestamp()
     where o.id = v_o.id;
    update rally100.entries
       set removed_at = pg_catalog.clock_timestamp(), merged_into = v_o.id,
           updated_at = pg_catalog.clock_timestamp()
     where id = v_x.id;
    update rally100.introductions set entry_id = v_o.id where entry_id = v_x.id;
    perform rally100._audit(v_me.id, v_me.team_id, 'entry', v_o.id, 'entry_merged',
                            pg_catalog.jsonb_build_object('merged', v_x.id));
    v_eff := rally100._settle(v_me.id, v_o.id, true, v_o.id);
    return rally100._save_shape(v_me.id, v_o.id, v_eff);
  end if;

  v_hx := rally100._handle_key(v_x.platform, v_x.handle, v_x.other_app);
  v_ho := rally100._handle_key(v_o.platform, v_o.handle, v_o.other_app);
  if not (v_x.phone <> '' and v_x.phone = v_o.phone) or (v_hx is not null and v_hx = v_ho) then
    perform rally100._fail('handle_match_needs_fix');
  end if;
  v_reason := rally100._text(p_reason, 300);
  if v_reason = '' then
    perform rally100._fail('reason_required');
  end if;
  update rally100.entries
     set kept_with = case when v_o.id = any (kept_with) then kept_with else kept_with || v_o.id end,
         kept_reason = v_reason, held_of = null, updated_at = pg_catalog.clock_timestamp()
   where id = v_x.id;
  update rally100.entries
     set kept_with = case when v_x.id = any (kept_with) then kept_with else kept_with || v_x.id end,
         kept_reason = v_reason, updated_at = pg_catalog.clock_timestamp()
   where id = v_o.id;
  perform rally100._audit(v_me.id, v_me.team_id, 'entry', v_x.id, 'entry_kept_both',
                          pg_catalog.jsonb_build_object('with', v_o.id, 'reason', v_reason));
  v_eff := rally100._settle(v_me.id, v_x.id, true, null);
  v_held := rally100._held_effect(v_x.id, null, true);
  if v_held is not null then
    v_eff := pg_catalog.jsonb_build_array(v_held) || v_eff;
  end if;
  return rally100._save_shape(v_me.id, v_x.id, v_eff);
end $$;

-- Removal is a tombstone: the entry, its Person and every record about them
-- stay. Removing it again is a no-op, not an error.
create function rally100.remove_entry(p_entry uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me  public.profiles := rally100._caller();
  v_x   rally100.entries%rowtype;
  v_eff pg_catalog.jsonb := '[]';
begin
  perform rally100._lock_rep(v_me.id);
  select * into v_x from rally100.entries where id = p_entry for update;
  if not found or v_x.rep_id <> v_me.id or v_x.merged_into is not null then
    perform rally100._deny('not_found');
  end if;
  if v_x.removed_at is null then
    update rally100.entries set removed_at = pg_catalog.clock_timestamp(),
                                updated_at = pg_catalog.clock_timestamp()
     where id = p_entry;
    perform rally100._audit(v_me.id, v_me.team_id, 'entry', p_entry, 'entry_removed', '{}'::pg_catalog.jsonb);
    v_eff := rally100._settle(v_me.id, p_entry, true, null);
  end if;
  return rally100._save_shape(v_me.id, p_entry, v_eff);
end $$;

-- Restore re-runs the duplicate check (the restored entry may hold, or be
-- held by, another); completed_at is already set, so it earns nothing again.
create function rally100.restore_entry(p_entry uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me   public.profiles := rally100._caller();
  v_x    rally100.entries%rowtype;
  v_eff  pg_catalog.jsonb := '[]';
  v_held pg_catalog.jsonb;
begin
  perform rally100._lock_rep(v_me.id);
  select * into v_x from rally100.entries where id = p_entry for update;
  if not found or v_x.rep_id <> v_me.id or v_x.merged_into is not null then
    perform rally100._deny('not_found');
  end if;
  if v_x.removed_at is not null then
    update rally100.entries set removed_at = null, updated_at = pg_catalog.clock_timestamp()
     where id = p_entry;
    perform rally100._audit(v_me.id, v_me.team_id, 'entry', p_entry, 'entry_restored', '{}'::pg_catalog.jsonb);
    v_eff := rally100._settle(v_me.id, p_entry, true, null);
    v_held := rally100._held_effect(p_entry, null, true);
    if v_held is not null then
      v_eff := pg_catalog.jsonb_build_array(v_held) || v_eff;
    end if;
  end if;
  return rally100._save_shape(v_me.id, p_entry, v_eff);
end $$;

/* An introduction starts from a contact the rep can actually hand over:
   complete (the leader needs the phone), counted, and not a Person who has
   asked not to be contacted. Shared by plan_intro and record_intro. */
create function rally100._intro_entry(p_me public.profiles, p_entry uuid)
returns rally100.entries
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_x rally100.entries%rowtype;
begin
  select * into v_x from rally100.entries where id = p_entry for update;
  if not found or v_x.rep_id <> p_me.id or v_x.merged_into is not null then
    perform rally100._deny('not_found');
  end if;
  if v_x.removed_at is not null then
    perform rally100._fail('entry_removed');
  end if;
  if not v_x.is_complete then
    perform rally100._fail('entry_not_complete');
  end if;
  -- before the Person check: a held entry is never linked to a Person
  if v_x.held_of is not null then
    perform rally100._fail('held_duplicate');
  end if;
  if v_x.person_id is null then
    perform rally100._fail('entry_not_complete');
  end if;
  if exists (select 1 from rally100.persons p where p.id = v_x.person_id and p.outcome = 'do_not_contact') then
    perform rally100._fail('do_not_contact');
  end if;
  return v_x;
end $$;

create function rally100.plan_intro(p_entry uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me public.profiles := rally100._caller();
  v_x  rally100.entries%rowtype;
  v_p  rally100.persons%rowtype;
begin
  perform rally100._lock_rep(v_me.id);
  v_x := rally100._intro_entry(v_me, p_entry);
  select * into v_p from rally100.persons where id = v_x.person_id for update;
  insert into rally100.introductions (person_id, rep_id, entry_id, status)
  values (v_x.person_id, v_me.id, v_x.id, 'planned')
  on conflict (person_id, rep_id) do nothing;
  if found then
    perform rally100._audit(v_me.id, v_me.team_id, 'person', v_x.person_id, 'intro_planned', '{}'::pg_catalog.jsonb);
  end if;
  if v_p.stage = 'added' then
    update rally100.persons set stage = 'intro_planned', updated_at = pg_catalog.clock_timestamp()
     where id = v_p.id;
    perform rally100._audit(v_me.id, v_me.team_id, 'person', v_p.id, 'stage',
                            pg_catalog.jsonb_build_object('from', 'added', 'to', 'intro_planned'));
  end if;
  return pg_catalog.jsonb_build_object('intro', rally100._intro_obj(v_x.id, v_me.id));
end $$;

/* "I introduced Marcus." recorded_at is server time and only the FIRST
   recording sets it (a re-save corrects the channel or the note, never the
   moment). Interest follows what the friend said unless a leader has already
   set it. The referral record is created here, once per Person. */
create function rally100.record_intro(p_entry uuid, p_channel text, p_said text,
                                      p_note text default null, p_date date default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me   public.profiles := rally100._caller();
  v_x    rally100.entries%rowtype;
  v_p    rally100.persons%rowtype;
  v_note pg_catalog.text;
  v_ix   integer;
begin
  perform rally100._lock_rep(v_me.id);
  v_x := rally100._intro_entry(v_me, p_entry);
  if p_channel is null or p_channel not in ('text', 'call', 'in_person', 'other') then
    perform rally100._fail('invalid_channel');
  end if;
  if p_said is null or p_said not in ('in', 'maybe', 'not_for_them', 'didnt_say') then
    perform rally100._fail('invalid_said');
  end if;
  v_note := rally100._text(p_note, 1000);
  select * into v_p from rally100.persons where id = v_x.person_id for update;

  insert into rally100.introductions as i
         (person_id, rep_id, entry_id, status, channel, said, note, intro_date, recorded_at)
  values (v_x.person_id, v_me.id, v_x.id, 'introduced', p_channel, p_said, v_note,
          coalesce(p_date, rally100._today()), pg_catalog.clock_timestamp())
  on conflict (person_id, rep_id) do update
     set status = 'introduced',
         channel = excluded.channel,
         said = excluded.said,
         note = excluded.note,
         intro_date = excluded.intro_date,
         recorded_at = coalesce(i.recorded_at, excluded.recorded_at),
         entry_id = coalesce(i.entry_id, excluded.entry_id);

  -- a leader's word on interest outranks a rep's report of what was said
  if not exists (select 1 from rally100.audit a
                  where a.entity = 'person' and a.entity_id = any (rally100._family(v_p.id))
                    and a.action = 'set_interest') then
    update rally100.persons
       set interest = case p_said when 'in' then 'interested' when 'maybe' then 'maybe'
                                  when 'not_for_them' then 'not_interested' else 'unknown' end,
           updated_at = pg_catalog.clock_timestamp()
     where id = v_p.id;
  end if;
  v_ix := rally100._stage_ix(v_p.stage);
  if v_ix < rally100._stage_ix('introduced') then
    update rally100.persons set stage = 'introduced', updated_at = pg_catalog.clock_timestamp()
     where id = v_p.id;
  end if;
  if v_p.responsible_leader is null then
    update rally100.persons set responsible_leader = rally100._team_leader(v_me.team_id)
     where id = v_p.id;
  end if;
  perform rally100._ensure_referral(v_p.id, v_me.team_id, v_me.id);
  perform rally100._audit(v_me.id, v_me.team_id, 'person', v_p.id, 'intro_recorded',
                          pg_catalog.jsonb_build_object('channel', p_channel, 'said', p_said,
                                                        'from_stage', v_p.stage));
  return pg_catalog.jsonb_build_object('intro', rally100._intro_obj(v_x.id, v_me.id));
end $$;

-- Follow up later, by the rep, only before the leader owns the stage.
create function rally100.set_follow_up(p_entry uuid, p_date date, p_note text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me   public.profiles := rally100._caller();
  v_x    rally100.entries%rowtype;
  v_p    rally100.persons%rowtype;
  v_note pg_catalog.text;
begin
  select * into v_x from rally100.entries where id = p_entry;
  if not found or v_x.rep_id <> v_me.id or v_x.merged_into is not null then
    perform rally100._deny('not_found');
  end if;
  if v_x.removed_at is not null then
    perform rally100._fail('entry_removed');
  end if;
  if v_x.person_id is null then
    perform rally100._fail('entry_not_complete');
  end if;
  select * into v_p from rally100.persons where id = v_x.person_id for update;
  if v_p.outcome = 'do_not_contact' then
    perform rally100._fail('do_not_contact');
  end if;
  if v_p.outcome = 'not_interested' then
    perform rally100._fail('outcome_locked');
  end if;
  if rally100._stage_ix(v_p.stage) > rally100._stage_ix('introduced') then
    perform rally100._fail('stage_locked');
  end if;
  if p_date is null then
    perform rally100._fail('date_required');
  end if;
  v_note := rally100._text(p_note, 1000);
  update rally100.persons
     set outcome = 'follow_up', outcome_date = p_date, outcome_note = v_note,
         updated_at = pg_catalog.clock_timestamp()
   where id = v_p.id;
  perform rally100._audit(v_me.id, v_me.team_id, 'person', v_p.id, 'outcome',
                          pg_catalog.jsonb_build_object('from', v_p.outcome, 'to', 'follow_up', 'date', p_date));
  return pg_catalog.jsonb_build_object('intro', rally100._intro_obj(v_x.id, v_me.id));
end $$;

create function rally100.tell_leader(p_entry uuid, p_body text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me   public.profiles := rally100._caller();
  v_x    rally100.entries%rowtype;
  v_body pg_catalog.text;
  v_id   pg_catalog.uuid;
begin
  select * into v_x from rally100.entries where id = p_entry;
  if not found or v_x.rep_id <> v_me.id or v_x.merged_into is not null then
    perform rally100._deny('not_found');
  end if;
  if v_x.person_id is null then
    perform rally100._fail('entry_not_complete');
  end if;
  v_body := rally100._text(p_body, 1000);
  if v_body = '' then
    perform rally100._fail('note_required');
  end if;
  insert into rally100.messages (person_id, rep_id, body) values (v_x.person_id, v_me.id, v_body)
  returning id into v_id;
  perform rally100._audit(v_me.id, v_me.team_id, 'person', v_x.person_id, 'message',
                          pg_catalog.jsonb_build_object('message_id', v_id));
  return pg_catalog.jsonb_build_object('ok', true);
end $$;

-- Only the two badges the server cannot see happen (a Sprint, a Sweep queue).
create function rally100.award_badge(p_badge text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me public.profiles := rally100._caller();
begin
  if p_badge is null or p_badge not in ('sprinter', 'clean_sweep') then
    perform rally100._fail('invalid_badge');
  end if;
  insert into rally100.badges (rep_id, badge) values (v_me.id, p_badge) on conflict do nothing;
  if found then
    perform rally100._audit(v_me.id, v_me.team_id, 'badge', v_me.id, 'badge',
                            pg_catalog.jsonb_build_object('badge', p_badge));
  end if;
  return pg_catalog.jsonb_build_object('badges',
    (select coalesce(pg_catalog.jsonb_agg(b.badge order by b.created_at, b.badge), '[]'::pg_catalog.jsonb)
       from rally100.badges b where b.rep_id = v_me.id));
end $$;

-- ------------------------------------------------------------- 6.3 leader

create function rally100.team_state()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_me   public.profiles := rally100._caller();
  v_reps pg_catalog.jsonb;
  v_q    pg_catalog.jsonb;
begin
  perform rally100._require_leader(v_me);
  select coalesce(pg_catalog.jsonb_agg(rally100._rep_row(p.id, v_me.role = 'owner')
                                       order by rally100._name(p.id), p.id), '[]'::pg_catalog.jsonb)
    into v_reps
    from public.profiles p
   where (v_me.role = 'owner' and p.team_id is not null) or p.team_id = v_me.team_id;
  v_q := rally100._queues(v_me);
  return pg_catalog.jsonb_build_object(
    'reps', v_reps,
    'queues', v_q,
    'counts', pg_catalog.jsonb_build_object(
      'new_intros', pg_catalog.jsonb_array_length(v_q -> 'new_intros'),
      'meetings', pg_catalog.jsonb_array_length(v_q -> 'meetings'),
      'follow_ups', pg_catalog.jsonb_array_length(v_q -> 'follow_ups'),
      'confirmations', pg_catalog.jsonb_array_length(v_q -> 'confirmations'),
      'reviews', pg_catalog.jsonb_array_length(v_q -> 'reviews'),
      'messages', pg_catalog.jsonb_array_length(v_q -> 'messages'),
      'matches', pg_catalog.jsonb_array_length(v_q -> 'matches')));
end $$;

/* Everything a leader's Person panel shows. A rep outside the caller's scope
   is "A rep on another team": no name, no id, no tags, no dates. History is
   the audit trail of this Person (and of anything merged into it) and of its
   referral record, newest first. */
create function rally100.person_detail(p_person uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_me  public.profiles := rally100._caller();
  v_fam pg_catalog.uuid[];
  v_rw  rally100.rewards%rowtype;
begin
  perform rally100._require_leader(v_me);
  if not rally100._person_in_scope(v_me, p_person) then
    perform rally100._deny('not_found');
  end if;
  v_fam := rally100._family(p_person);
  select * into v_rw from rally100.rewards r where r.kind = 'referral' and r.person_id = p_person;
  return pg_catalog.jsonb_build_object(
    'person', rally100._person_json(p_person),
    'entries', (select coalesce(pg_catalog.jsonb_agg(
                         case when rally100._rep_in_scope(v_me, e.rep_id) then
                           pg_catalog.jsonb_build_object(
                             'rep_id', e.rep_id, 'rep_name', rally100._name(e.rep_id),
                             'added_at', e.created_at, 'tags', pg_catalog.to_jsonb(e.tags),
                             'introduced', i.status is not distinct from 'introduced',
                             'recorded_at', i.recorded_at, 'received_at', i.received_at)
                         else pg_catalog.jsonb_build_object('rep_name', 'A rep on another team') end
                         order by e.created_at, e.id), '[]'::pg_catalog.jsonb)
                  from rally100.entries e
                  left join rally100.introductions i on i.person_id = e.person_id and i.rep_id = e.rep_id
                 where e.person_id = p_person and e.removed_at is null and e.merged_into is null),
    'identifiers', (select coalesce(pg_catalog.jsonb_agg(distinct pg_catalog.jsonb_build_object('kind', x.kind, 'value', x.value)),
                                    '[]'::pg_catalog.jsonb)
                      from rally100.person_identifiers x where x.person_id = any (v_fam)),
    'requirements', rally100._reqs_json(p_person, true),
    'reward', rally100._reward_json(v_rw, v_me),
    'notes', (select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                       'id', n.id, 'author_name', rally100._name(n.author), 'body', n.body, 'created_at', n.created_at)
                       order by n.created_at desc, n.id), '[]'::pg_catalog.jsonb)
                from rally100.notes n where n.person_id = any (v_fam)),
    'messages', (select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                          'id', m.id, 'rep_name', rally100._name(m.rep_id), 'body', m.body,
                          'created_at', m.created_at, 'read_at', m.read_at)
                          order by m.created_at desc, m.id), '[]'::pg_catalog.jsonb)
                   from rally100.messages m
                  where m.person_id = any (v_fam) and rally100._rep_in_scope(v_me, m.rep_id)),
    /* A leader's history leaves out what reps on other teams did (the
       blueprint's "no name, tags or date" for them), strips the id of an
       out-of-scope credited rep from the server's own entries, and never
       carries the owner's internal reversal reason. The owner sees every row
       as written. */
    'history', (select coalesce(pg_catalog.jsonb_agg(h.obj order by h.id desc), '[]'::pg_catalog.jsonb)
                  from (select a.id, pg_catalog.jsonb_build_object(
                                 'at', a.created_at,
                                 'actor_name', case when a.actor is null then 'RALLY'
                                                    else rally100._name(a.actor) end,
                                 'action', a.action,
                                 'detail', case
                                   when v_me.role = 'owner' then a.detail
                                   else (case
                                           when a.detail ? 'rep_id'
                                                and (a.detail ->> 'rep_id') ~ '^[0-9a-f-]{36}$'
                                                and not rally100._rep_in_scope(v_me, (a.detail ->> 'rep_id')::pg_catalog.uuid)
                                             then a.detail - 'rep_id' - 'basis'
                                           else a.detail end)
                                        - case when a.action in ('reverse', 'close_unpaid') then 'reason' else '' end
                                   end) as obj
                          from rally100.audit a
                         where ((a.entity = 'person' and a.entity_id = any (v_fam))
                                or (a.entity = 'reward' and v_rw.id is not null and a.entity_id = v_rw.id))
                           and (v_me.role = 'owner' or a.actor is null
                                or rally100._rep_in_scope(v_me, a.actor)
                                or exists (select 1 from public.profiles o where o.id = a.actor
                                            and o.role in ('leader', 'manager', 'owner')))
                         order by a.id desc
                         limit 100) h));
end $$;

/* "Confirm introduction received." Once per (Person, rep): it timestamps the
   receipt, grants the rep introduction_made (+100 XP, keyed in:<person>),
   makes the caller the responsible leader if nobody is, checks the rep's
   first_intro and matchmaker badges, and — because a received introduction
   is what crediting waits for — re-applies rule 9 to a referral that already
   has all four confirmations. Nobody confirms their own introduction. */
create function rally100.confirm_intro_received(p_person uuid, p_rep uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me  public.profiles := rally100._caller();
  v_p   rally100.persons%rowtype;
  v_i   rally100.introductions%rowtype;
  v_n   integer;
begin
  perform rally100._require_leader(v_me);
  v_p := rally100._person_for_write(v_me, p_person);
  if not rally100._rep_in_scope(v_me, p_rep) then
    perform rally100._deny('not_found');
  end if;
  if p_rep = v_me.id then
    perform rally100._deny('self_involved');
  end if;
  select * into v_i from rally100.introductions where person_id = p_person and rep_id = p_rep for update;
  if not found then
    perform rally100._deny('not_found');
  end if;
  if v_i.status <> 'introduced' then
    perform rally100._fail('intro_not_recorded');
  end if;
  if v_i.received_at is not null then
    return pg_catalog.jsonb_build_object('ok', true);
  end if;

  update rally100.introductions set received_by = v_me.id, received_at = pg_catalog.clock_timestamp()
   where id = v_i.id;
  if v_p.responsible_leader is null then
    update rally100.persons set responsible_leader = v_me.id, updated_at = pg_catalog.clock_timestamp()
     where id = v_p.id;
  end if;
  perform rally100._xp(p_rep, 'in:' || p_person::pg_catalog.text, 100, 'introduction_made');
  select pg_catalog.count(*) into v_n from rally100.introductions where rep_id = p_rep and received_at is not null;
  if v_n >= 1 then
    insert into rally100.badges (rep_id, badge) values (p_rep, 'first_intro') on conflict do nothing;
  end if;
  if v_n >= 3 then
    insert into rally100.badges (rep_id, badge) values (p_rep, 'matchmaker') on conflict do nothing;
  end if;
  perform rally100._audit(v_me.id, v_me.team_id, 'person', p_person, 'intro_received',
                          pg_catalog.jsonb_build_object('rep_id', p_rep));
  perform rally100._referral_eval(p_person, v_me.id);
  return pg_catalog.jsonb_build_object('ok', true);
end $$;

/* Leaders own meeting_scheduled onward. A leader may move a Person BACK to
   any stage (with a reason, kept in history), but never forward into a stage
   the rep sets by recording an introduction. A stage never ticks a
   requirement. */
create function rally100.set_stage(p_person uuid, p_stage text, p_date date default null,
                                   p_note text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me   public.profiles := rally100._caller();
  v_p    rally100.persons%rowtype;
  v_note pg_catalog.text;
  v_from integer;
  v_to   integer;
begin
  perform rally100._require_leader(v_me);
  v_p := rally100._person_for_write(v_me, p_person);
  v_to := rally100._stage_ix(p_stage);
  if v_to is null then
    perform rally100._fail('invalid_stage');
  end if;
  v_note := rally100._text(p_note, 1000);
  v_from := rally100._stage_ix(v_p.stage);
  if v_to = v_from then
    return pg_catalog.jsonb_build_object('person', rally100._person_json(p_person));
  end if;
  if v_to > v_from and v_to < rally100._stage_ix('meeting_scheduled') then
    perform rally100._fail('invalid_stage');
  end if;
  if v_to < v_from and v_note = '' then
    perform rally100._fail('reason_required');
  end if;
  update rally100.persons set stage = p_stage, updated_at = pg_catalog.clock_timestamp() where id = p_person;
  perform rally100._audit(v_me.id, v_me.team_id, 'person', p_person, 'stage',
                          pg_catalog.jsonb_build_object('from', v_p.stage, 'to', p_stage, 'date', p_date, 'note', v_note));
  return pg_catalog.jsonb_build_object('person', rally100._person_json(p_person));
end $$;

create function rally100.schedule_meeting(p_person uuid, p_at timestamptz, p_how text default null,
                                          p_note text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me   public.profiles := rally100._caller();
  v_p    rally100.persons%rowtype;
  v_how  pg_catalog.text;
  v_note pg_catalog.text;
begin
  perform rally100._require_leader(v_me);
  v_p := rally100._person_for_write(v_me, p_person);
  if p_at is null then
    perform rally100._fail('date_required');
  end if;
  v_how := rally100._text(p_how, 40);
  v_note := rally100._text(p_note, 1000);
  update rally100.persons
     set meeting_at = p_at, meeting_how = v_how, meeting_note = v_note,
         stage = case when rally100._stage_ix(stage) < rally100._stage_ix('meeting_scheduled')
                      then 'meeting_scheduled' else stage end,
         updated_at = pg_catalog.clock_timestamp()
   where id = p_person;
  perform rally100._audit(v_me.id, v_me.team_id, 'person', p_person, 'meeting',
                          pg_catalog.jsonb_build_object('at', p_at, 'how', v_how, 'from_stage', v_p.stage));
  return pg_catalog.jsonb_build_object('person', rally100._person_json(p_person));
end $$;

/* RULES 9 AND 10. Each requirement is confirmed on its own, by a named
   leader, with a date. Requirement 4 needs a start date and either a travel
   note or travel_na. Confirming creates the referral record if nothing has
   yet (a leader may confirm before any rep recorded an introduction; the
   record then carries no_intro for the owner). Unticking needs a reason, is
   refused once the reward is approved or paid (only an owner reversal applies
   then), and otherwise returns the reward to In progress with the credit
   cleared. */
create function rally100.set_requirement(p_person uuid, p_req integer, p_confirmed boolean,
                                         p_event_date date default null, p_note text default null,
                                         p_start_date date default null, p_travel_note text default null,
                                         p_travel_na boolean default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me     public.profiles := rally100._caller();
  v_p      rally100.persons%rowtype;
  v_had    boolean;
  v_status pg_catalog.text;
  v_note   pg_catalog.text;
  v_start  pg_catalog.date;
  v_travel pg_catalog.text;
  v_na     boolean;
  v_rw     rally100.rewards%rowtype;
begin
  perform rally100._require_leader(v_me);
  v_p := rally100._person_for_write(v_me, p_person);
  if p_req is null or p_req not between 1 and 4 then
    perform rally100._fail('invalid_req');
  end if;
  if p_confirmed is null then
    perform rally100._fail('invalid_payload');
  end if;
  v_note := rally100._text(p_note, 1000);
  select coalesce(r.confirmed, false) into v_had from rally100.requirements r
   where r.person_id = p_person and r.req = p_req for update;
  v_had := coalesce(v_had, false);
  select r.status into v_status from rally100.rewards r where r.kind = 'referral' and r.person_id = p_person;

  if p_confirmed then
    if v_had and v_status in ('approved', 'paid') then
      null;   -- already confirmed on a locked record: nothing to change
    else
      if p_req = 4 then
        v_start := coalesce(p_start_date, v_p.start_date);
        v_travel := case when p_travel_note is not null then rally100._text(p_travel_note, 1000)
                         else v_p.travel_note end;
        v_na := coalesce(p_travel_na, v_p.travel_na);
        if v_start is null then
          perform rally100._fail('start_date_required');
        end if;
        if v_travel = '' and not v_na then
          perform rally100._fail('travel_required');
        end if;
        update rally100.persons set start_date = v_start, travel_note = v_travel, travel_na = v_na,
                                    updated_at = pg_catalog.clock_timestamp()
         where id = p_person;
      end if;
      insert into rally100.requirements as q (person_id, req, confirmed, confirmed_by, event_date, note, updated_at)
      values (p_person, p_req, true, v_me.id, coalesce(p_event_date, rally100._today()), v_note,
              pg_catalog.clock_timestamp())
      on conflict (person_id, req) do update
         set confirmed = true, confirmed_by = excluded.confirmed_by, event_date = excluded.event_date,
             note = excluded.note, updated_at = excluded.updated_at;
      perform rally100._audit(v_me.id, v_me.team_id, 'person', p_person, 'requirement_confirmed',
                              pg_catalog.jsonb_build_object('req', p_req,
                                'event_date', coalesce(p_event_date, rally100._today()), 'note', v_note));
      perform rally100._ensure_referral(p_person, v_me.team_id, v_me.id);
      perform rally100._referral_eval(p_person, v_me.id);
    end if;
  elsif v_had then
    if v_status in ('approved', 'paid') then
      perform rally100._fail('locked_reward');
    end if;
    if v_note = '' then
      perform rally100._fail('reason_required');
    end if;
    update rally100.requirements
       set confirmed = false, confirmed_by = v_me.id, event_date = null, note = v_note,
           updated_at = pg_catalog.clock_timestamp()
     where person_id = p_person and req = p_req;
    perform rally100._audit(v_me.id, v_me.team_id, 'person', p_person, 'requirement_unticked',
                            pg_catalog.jsonb_build_object('req', p_req, 'reason', v_note));
    perform rally100._referral_untick(p_person, v_me.id, v_note);
  end if;

  select * into v_rw from rally100.rewards r where r.kind = 'referral' and r.person_id = p_person;
  return pg_catalog.jsonb_build_object(
    'person', rally100._person_json(p_person),
    'requirements', rally100._reqs_json(p_person, true),
    'reward', rally100._reward_json(v_rw, v_me));
end $$;

/* Outcomes sit beside the stage. Follow up later needs a date, Not interested
   a note (and records the interest), Do not contact nothing — honouring it
   matters more than explaining it. Clearing (or replacing) Do not contact is
   the owner's alone. Setting or clearing it moves the count of every rep who
   has this Person, so their count-driven effects are settled here. */
create function rally100.set_outcome(p_person uuid, p_outcome text, p_date date default null,
                                     p_note text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me   public.profiles := rally100._caller();
  v_p    rally100.persons%rowtype;
  v_note pg_catalog.text;
begin
  perform rally100._require_leader(v_me);
  v_p := rally100._person_for_write(v_me, p_person);
  if p_outcome is not null and p_outcome not in ('follow_up', 'not_interested', 'do_not_contact') then
    perform rally100._fail('invalid_outcome');
  end if;
  if v_p.outcome = 'do_not_contact' and p_outcome is distinct from 'do_not_contact' and v_me.role <> 'owner' then
    perform rally100._deny('owner_only');
  end if;
  v_note := rally100._text(p_note, 1000);
  if p_outcome = 'follow_up' and p_date is null then
    perform rally100._fail('date_required');
  end if;
  if p_outcome = 'not_interested' and v_note = '' then
    perform rally100._fail('note_required');
  end if;

  update rally100.persons
     set outcome = p_outcome,
         outcome_date = case when p_outcome is null then null else p_date end,
         outcome_note = case when p_outcome is null then '' else v_note end,
         interest = case when p_outcome = 'not_interested' then 'not_interested' else interest end,
         updated_at = pg_catalog.clock_timestamp()
   where id = p_person;
  perform rally100._audit(v_me.id, v_me.team_id, 'person', p_person, 'outcome',
                          pg_catalog.jsonb_build_object('from', v_p.outcome, 'to', p_outcome,
                                                        'date', p_date, 'note', v_note));
  if p_outcome = 'not_interested' then
    perform rally100._audit(v_me.id, v_me.team_id, 'person', p_person, 'set_interest',
                            pg_catalog.jsonb_build_object('from', v_p.interest, 'to', 'not_interested'));
  end if;
  if (v_p.outcome = 'do_not_contact') is distinct from (p_outcome = 'do_not_contact') then
    perform rally100._settle_person_reps(p_person);
  end if;
  return pg_catalog.jsonb_build_object('person', rally100._person_json(p_person));
end $$;

create function rally100.set_interest(p_person uuid, p_interest text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me public.profiles := rally100._caller();
  v_p  rally100.persons%rowtype;
begin
  perform rally100._require_leader(v_me);
  v_p := rally100._person_for_write(v_me, p_person);
  if p_interest is null or p_interest not in ('unknown', 'interested', 'maybe', 'not_interested') then
    perform rally100._fail('invalid_interest');
  end if;
  update rally100.persons set interest = p_interest, updated_at = pg_catalog.clock_timestamp()
   where id = p_person;
  perform rally100._audit(v_me.id, v_me.team_id, 'person', p_person, 'set_interest',
                          pg_catalog.jsonb_build_object('from', v_p.interest, 'to', p_interest));
  return pg_catalog.jsonb_build_object('ok', true);
end $$;

create function rally100.set_next_action(p_person uuid, p_text text, p_owner uuid default null,
                                         p_date date default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me   public.profiles := rally100._caller();
  v_p    rally100.persons%rowtype;
  v_text pg_catalog.text;
begin
  perform rally100._require_leader(v_me);
  v_p := rally100._person_for_write(v_me, p_person);
  v_text := rally100._text(p_text, 200);
  if p_owner is not null and not rally100._rep_in_scope(v_me, p_owner) then
    perform rally100._deny('not_found');
  end if;
  update rally100.persons
     set next_action = v_text, next_action_owner = p_owner, next_action_date = p_date,
         updated_at = pg_catalog.clock_timestamp()
   where id = p_person;
  perform rally100._audit(v_me.id, v_me.team_id, 'person', p_person, 'next_action',
                          pg_catalog.jsonb_build_object('text', v_text, 'owner', p_owner, 'date', p_date));
  return pg_catalog.jsonb_build_object('ok', true);
end $$;

create function rally100.add_note(p_person uuid, p_body text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me   public.profiles := rally100._caller();
  v_body pg_catalog.text;
  v_id   pg_catalog.uuid;
begin
  perform rally100._require_leader(v_me);
  perform rally100._person_for_write(v_me, p_person);
  v_body := rally100._text(p_body, 2000);
  if v_body = '' then
    perform rally100._fail('note_required');
  end if;
  insert into rally100.notes (person_id, author, body) values (p_person, v_me.id, v_body)
  returning id into v_id;
  perform rally100._audit(v_me.id, v_me.team_id, 'person', p_person, 'note',
                          pg_catalog.jsonb_build_object('note_id', v_id));
  return pg_catalog.jsonb_build_object('ok', true);
end $$;

create function rally100.mark_messages_read(p_person uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me public.profiles := rally100._caller();
  v_n  integer;
begin
  perform rally100._require_leader(v_me);
  if not rally100._person_in_scope(v_me, p_person) then
    perform rally100._deny('not_found');
  end if;
  update rally100.messages m set read_by = v_me.id, read_at = pg_catalog.clock_timestamp()
   where m.person_id = any (rally100._family(p_person)) and m.read_at is null
     and rally100._rep_in_scope(v_me, m.rep_id);
  get diagnostics v_n = row_count;
  if v_n > 0 then
    perform rally100._audit(v_me.id, v_me.team_id, 'person', p_person, 'messages_read',
                            pg_catalog.jsonb_build_object('count', v_n));
  end if;
  return pg_catalog.jsonb_build_object('ok', true);
end $$;

-- The walkthrough: the rep's whole list, and a sample of 3 to 5 counted
-- entries that stays the same all (org) day, so a refresh does not reshuffle
-- the leader's questions mid-conversation.
create function rally100.rep_list(p_rep uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_me public.profiles := rally100._caller();
  v_c  record;
begin
  perform rally100._require_leader(v_me);
  if not rally100._rep_in_scope(v_me, p_rep) then
    perform rally100._deny('not_found');
  end if;
  select * into v_c from rally100._rep_counts(p_rep);
  return pg_catalog.jsonb_build_object(
    'rep', pg_catalog.jsonb_build_object('id', p_rep, 'name', rally100._name(p_rep)),
    'count', v_c.o_count,
    'entries', rally100._entries_json(p_rep),
    'sample', (select coalesce(pg_catalog.jsonb_agg(rally100._entry_json(s.e) order by s.k), '[]'::pg_catalog.jsonb)
                 from (select e, pg_catalog.md5(e.id::pg_catalog.text || rally100._today()::pg_catalog.text) as k
                         from rally100.entries e
                         left join rally100.persons p on p.id = e.person_id
                        where e.rep_id = p_rep and e.is_complete and e.removed_at is null
                          and e.held_of is null and e.merged_into is null
                          and coalesce(p.outcome, '') <> 'do_not_contact'
                        order by 2
                        limit 5) s));
end $$;

/* The walkthrough spot-check, for a List Completion reward: 3 to 5 of that
   rep's counted entries, each looks_real / unclear / not_real. looks_real
   writes the entry's verified mark. The newest spot-check is the one the
   reward points at; earlier ones stay in the table as history. */
create function rally100.record_spot_check(p_reward uuid, p_results jsonb, p_note text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me   public.profiles := rally100._caller();
  v_r    rally100.rewards%rowtype;
  v_note pg_catalog.text;
  v_res  pg_catalog.jsonb := '[]';
  v_seen pg_catalog.uuid[] := '{}';
  v_eid  pg_catalog.uuid;
  v_sc   pg_catalog.uuid;
  x      pg_catalog.jsonb;
begin
  perform rally100._require_leader(v_me);
  select * into v_r from rally100.rewards where id = p_reward for update;
  if not found or not rally100._reward_in_scope(v_me, v_r) then
    perform rally100._deny('not_found');
  end if;
  if v_r.kind <> 'list' then
    perform rally100._fail('not_list_reward');
  end if;
  if v_r.rep_id = v_me.id then
    perform rally100._deny('self_involved');
  end if;
  if v_r.reversed_at is not null then
    perform rally100._fail('reward_reversed');
  end if;
  if v_r.status not in ('ready', 'needs_correction') then
    perform rally100._fail('not_ready');
  end if;
  v_note := rally100._text(p_note, 1000);
  if p_results is null or pg_catalog.jsonb_typeof(p_results) <> 'array'
     or pg_catalog.jsonb_array_length(p_results) not between 3 and 5 then
    perform rally100._fail('spot_check_size');
  end if;
  for x in select y from pg_catalog.jsonb_array_elements(p_results) y loop
    if pg_catalog.jsonb_typeof(x) <> 'object'
       or coalesce(x ->> 'entry_id', '') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
      perform rally100._fail('spot_check_entry');
    end if;
    if coalesce(x ->> 'result', '') not in ('looks_real', 'unclear', 'not_real') then
      perform rally100._fail('invalid_result');
    end if;
    v_eid := (x ->> 'entry_id')::pg_catalog.uuid;
    if v_eid = any (v_seen) or not exists (
         select 1 from rally100.entries e left join rally100.persons p on p.id = e.person_id
          where e.id = v_eid and e.rep_id = v_r.rep_id and e.is_complete and e.removed_at is null
            and e.held_of is null and e.merged_into is null and coalesce(p.outcome, '') <> 'do_not_contact') then
      perform rally100._fail('spot_check_entry');
    end if;
    v_seen := v_seen || v_eid;
    v_res := v_res || pg_catalog.jsonb_build_object('entry_id', v_eid, 'result', x ->> 'result');
  end loop;

  insert into rally100.spot_checks (reward_id, rep_id, leader_id, results, note)
  values (v_r.id, v_r.rep_id, v_me.id, v_res, v_note)
  returning id into v_sc;
  update rally100.rewards set spot_check_id = v_sc, updated_at = pg_catalog.clock_timestamp() where id = v_r.id;
  update rally100.entries e set verified_at = pg_catalog.clock_timestamp(), verified_by = v_me.id
   where e.id in (select (y ->> 'entry_id')::pg_catalog.uuid from pg_catalog.jsonb_array_elements(v_res) y
                   where y ->> 'result' = 'looks_real');
  perform rally100._reward_event(v_r.id, 'spot_check', v_r.status, v_r.status, v_me.id, v_note);
  perform rally100._audit(v_me.id, v_me.team_id, 'reward', v_r.id, 'spot_check',
                          pg_catalog.jsonb_build_object('spot_check_id', v_sc, 'results', v_res));
  select * into v_r from rally100.rewards where id = p_reward;
  return pg_catalog.jsonb_build_object('reward', rally100._reward_json(v_r, v_me));
end $$;

/* RULE 12, in one place for every review action. Nobody acts on a reward
   credited to themselves; an owner's own reward is acted on only by another
   owner. */
create function rally100._review_guard(p_me public.profiles, p_r rally100.rewards)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if p_r.rep_id = p_me.id then
    perform rally100._deny('self_involved');
  end if;
  if p_me.role <> 'owner'
     and exists (select 1 from public.profiles o where o.id = p_r.rep_id and o.role = 'owner') then
    perform rally100._deny('owner_only');
  end if;
end $$;

create function rally100.review_reward(p_reward uuid, p_action text, p_note text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me    public.profiles := rally100._caller();
  v_r     rally100.rewards%rowtype;
  v_note  pg_catalog.text;
  v_count integer;
begin
  perform rally100._require_leader(v_me);
  select * into v_r from rally100.rewards where id = p_reward for update;
  if not found or not rally100._reward_in_scope(v_me, v_r) then
    perform rally100._deny('not_found');
  end if;
  if p_action is null or p_action not in ('approve', 'needs_correction') then
    perform rally100._fail('invalid_action');
  end if;
  perform rally100._review_guard(v_me, v_r);
  if v_r.reversed_at is not null then
    perform rally100._fail('reward_reversed');
  end if;
  v_note := rally100._text(p_note, 1000);

  if p_action = 'approve' then
    if v_r.status in ('approved', 'paid') then
      return pg_catalog.jsonb_build_object('reward', rally100._reward_json(v_r, v_me));   -- a retried approve
    end if;
    if v_r.status <> 'ready' then
      perform rally100._fail('not_ready');
    end if;
    if v_r.kind = 'list' then
      select c.o_count into v_count from rally100._rep_counts(v_r.rep_id) c;
      if v_count < 100 then
        perform rally100._fail('count_below_100');
      end if;
      if v_r.spot_check_id is null then
        perform rally100._fail('spot_check_required');
      end if;
    end if;
    if v_r.kind = 'referral' and v_r.rep_id is null then
      perform rally100._fail('no_credited_rep');
    end if;
    update rally100.rewards
       set status = 'approved', approved_by = v_me.id, approved_at = pg_catalog.clock_timestamp(),
           updated_at = pg_catalog.clock_timestamp()
     where id = v_r.id;
    perform rally100._reward_event(v_r.id, 'approve', 'ready', 'approved', v_me.id, v_note);
  else
    if v_note = '' then
      perform rally100._fail('note_required');
    end if;
    if v_r.status = 'needs_correction' then
      return pg_catalog.jsonb_build_object('reward', rally100._reward_json(v_r, v_me));
    end if;
    if v_r.status <> 'ready' then
      perform rally100._fail('not_ready');
    end if;
    update rally100.rewards
       set status = 'needs_correction', correction_note = v_note, correction_by = v_me.id,
           updated_at = pg_catalog.clock_timestamp()
     where id = v_r.id;
    perform rally100._reward_event(v_r.id, 'needs_correction', 'ready', 'needs_correction', v_me.id, v_note);
  end if;
  perform rally100._audit(v_me.id, v_me.team_id, 'reward', v_r.id, p_action,
                          pg_catalog.jsonb_build_object('note', v_note));
  select * into v_r from rally100.rewards where id = p_reward;
  return pg_catalog.jsonb_build_object('reward', rally100._reward_json(v_r, v_me));
end $$;

-- needs_correction back to ready: by whoever raised it, or the owner
create function rally100.resolve_correction(p_reward uuid, p_note text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me   public.profiles := rally100._caller();
  v_r    rally100.rewards%rowtype;
  v_note pg_catalog.text;
begin
  perform rally100._require_leader(v_me);
  select * into v_r from rally100.rewards where id = p_reward for update;
  if not found or not rally100._reward_in_scope(v_me, v_r) then
    perform rally100._deny('not_found');
  end if;
  v_note := rally100._text(p_note, 1000);
  if v_r.status = 'ready' then
    return pg_catalog.jsonb_build_object('reward', rally100._reward_json(v_r, v_me));
  end if;
  if v_r.status <> 'needs_correction' then
    perform rally100._fail('not_ready');
  end if;
  if v_r.correction_by is distinct from v_me.id and v_me.role <> 'owner' then
    perform rally100._deny('not_allowed');
  end if;
  update rally100.rewards set status = 'ready', updated_at = pg_catalog.clock_timestamp() where id = v_r.id;
  perform rally100._reward_event(v_r.id, 'resolve_correction', 'needs_correction', 'ready', v_me.id, v_note);
  perform rally100._audit(v_me.id, v_me.team_id, 'reward', v_r.id, 'resolve_correction',
                          pg_catalog.jsonb_build_object('note', v_note));
  select * into v_r from rally100.rewards where id = p_reward;
  return pg_catalog.jsonb_build_object('reward', rally100._reward_json(v_r, v_me));
end $$;

/* MERGE Person p_loser INTO p_survivor. Identifiers, entries, introductions
   and confirmed requirements move to the survivor; the loser keeps its id
   with merged_into (an alias, so the one-per-Person key still refuses a
   second referral for either id) and keeps everything append-only that was
   written to it, read through rally100._family(). Do not contact on either
   side wins. Afterwards every affected rep's holds and counts are settled,
   and rule 9 is re-applied to the survivor. */
create function rally100._merge_person(p_survivor uuid, p_loser uuid, p_actor uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_s rally100.persons%rowtype;
  v_l rally100.persons%rowtype;
  i   record;
  r   record;
begin
  select * into v_s from rally100.persons where id = p_survivor;
  select * into v_l from rally100.persons where id = p_loser;

  insert into rally100.person_identifiers (person_id, kind, value)
  select p_survivor, x.kind, x.value from rally100.person_identifiers x where x.person_id = p_loser
  on conflict do nothing;

  update rally100.entries set person_id = p_survivor where person_id = p_loser;

  for i in select * from rally100.introductions where person_id = p_loser loop
    if exists (select 1 from rally100.introductions t where t.person_id = p_survivor and t.rep_id = i.rep_id) then
      update rally100.introductions t
         set status = case when t.status = 'introduced' or i.status = 'introduced' then 'introduced' else 'planned' end,
             recorded_at = least(t.recorded_at, i.recorded_at),
             received_by = case when i.received_at is not null
                                     and (t.received_at is null or i.received_at < t.received_at)
                                then i.received_by else t.received_by end,
             received_at = least(t.received_at, i.received_at),
             channel = coalesce(t.channel, i.channel),
             said = coalesce(t.said, i.said)
       where t.person_id = p_survivor and t.rep_id = i.rep_id;
    else
      update rally100.introductions set person_id = p_survivor where id = i.id;
    end if;
  end loop;

  insert into rally100.requirements as q (person_id, req, confirmed, confirmed_by, event_date, note, updated_at)
  select p_survivor, x.req, true, x.confirmed_by, x.event_date, x.note, pg_catalog.clock_timestamp()
    from rally100.requirements x where x.person_id = p_loser and x.confirmed
  on conflict (person_id, req) do update
     set confirmed = true, confirmed_by = excluded.confirmed_by, event_date = excluded.event_date,
         note = excluded.note, updated_at = excluded.updated_at
   where not q.confirmed;

  update rally100.persons s
     set first_name = case when s.first_name = '' then v_l.first_name else s.first_name end,
         last_name = case when s.last_name = '' then v_l.last_name else s.last_name end,
         stage = case when rally100._stage_ix(v_l.stage) > rally100._stage_ix(s.stage) then v_l.stage else s.stage end,
         outcome = case when v_l.outcome = 'do_not_contact' or s.outcome is null then coalesce(v_l.outcome, s.outcome)
                        else s.outcome end,
         outcome_date = case when v_l.outcome = 'do_not_contact' or s.outcome is null
                             then case when v_l.outcome is not null then v_l.outcome_date else s.outcome_date end
                             else s.outcome_date end,
         outcome_note = case when v_l.outcome = 'do_not_contact' or s.outcome is null
                             then case when v_l.outcome is not null then v_l.outcome_note else s.outcome_note end
                             else s.outcome_note end,
         interest = case when s.interest = 'unknown' then v_l.interest else s.interest end,
         responsible_leader = coalesce(s.responsible_leader, v_l.responsible_leader),
         next_action = case when s.next_action = '' then v_l.next_action else s.next_action end,
         next_action_owner = case when s.next_action = '' then v_l.next_action_owner else s.next_action_owner end,
         next_action_date = case when s.next_action = '' then v_l.next_action_date else s.next_action_date end,
         meeting_at = coalesce(s.meeting_at, v_l.meeting_at),
         meeting_how = case when s.meeting_how = '' then v_l.meeting_how else s.meeting_how end,
         meeting_note = case when s.meeting_note = '' then v_l.meeting_note else s.meeting_note end,
         start_date = coalesce(s.start_date, v_l.start_date),
         travel_note = case when s.travel_note = '' then v_l.travel_note else s.travel_note end,
         travel_na = s.travel_na or v_l.travel_na,
         updated_at = pg_catalog.clock_timestamp()
   where s.id = p_survivor;
  update rally100.persons set merged_into = p_survivor, updated_at = pg_catalog.clock_timestamp()
   where id = p_loser;

  for r in select distinct e.rep_id from rally100.entries e where e.person_id = p_survivor order by e.rep_id loop
    perform rally100._dedupe(r.rep_id);
    perform rally100._settle(r.rep_id, null, false, null);
  end loop;
  perform rally100._referral_eval(p_survivor, p_actor);
end $$;

/* Resolve a possible match. link merges B into A — unless only B carries a
   referral record, in which case A merges into B, because the Person with a
   reward record is always the survivor (the record's history stays where it
   was written). Refused when both carry one: two referral records for one
   human is a question for the owner (reverse one first), not something a
   merge may quietly decide. Every rep with an entry on either Person is
   locked first, in id order, so the merge cannot interleave with their saves. */
create function rally100.link_persons(p_match uuid, p_action text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me  public.profiles := rally100._caller();
  v_m   rally100.possible_matches%rowtype;
  v_a   rally100.persons%rowtype;
  v_b   rally100.persons%rowtype;
  v_ra  boolean;
  v_rb  boolean;
  r     record;
begin
  perform rally100._require_leader(v_me);
  if p_action is null or p_action not in ('link', 'dismiss') then
    perform rally100._fail('invalid_action');
  end if;
  select * into v_m from rally100.possible_matches where id = p_match;
  if not found
     or not (v_me.role = 'owner'
             or (rally100._person_in_scope(v_me, v_m.person_a) and rally100._person_in_scope(v_me, v_m.person_b))) then
    perform rally100._deny('not_found');
  end if;

  for r in select distinct e.rep_id from rally100.entries e
            where e.person_id in (v_m.person_a, v_m.person_b) order by e.rep_id loop
    perform rally100._lock_rep(r.rep_id);
  end loop;
  select * into v_m from rally100.possible_matches where id = p_match for update;
  select * into v_a from rally100.persons where id = least(v_m.person_a, v_m.person_b) for update;
  select * into v_b from rally100.persons where id = greatest(v_m.person_a, v_m.person_b) for update;
  select * into v_a from rally100.persons where id = v_m.person_a;
  select * into v_b from rally100.persons where id = v_m.person_b;

  if p_action = 'dismiss' then
    if v_m.status = 'dismissed' then
      return pg_catalog.jsonb_build_object('ok', true);
    end if;
    if v_m.status <> 'open' then
      perform rally100._fail('match_closed');
    end if;
    update rally100.possible_matches
       set status = 'dismissed', resolved_by = v_me.id, resolved_at = pg_catalog.clock_timestamp()
     where id = p_match;
    perform rally100._audit(v_me.id, v_me.team_id, 'person', v_m.person_a, 'match_dismissed',
                            pg_catalog.jsonb_build_object('match_id', p_match, 'other', v_m.person_b));
    return pg_catalog.jsonb_build_object('ok', true);
  end if;

  if v_m.status = 'linked' then
    return pg_catalog.jsonb_build_object('ok', true);
  end if;
  if v_m.status <> 'open' or v_a.merged_into is not null or v_b.merged_into is not null then
    perform rally100._fail('match_closed');
  end if;
  v_ra := exists (select 1 from rally100.rewards x where x.kind = 'referral' and x.person_id = v_a.id);
  v_rb := exists (select 1 from rally100.rewards x where x.kind = 'referral' and x.person_id = v_b.id);
  if v_ra and v_rb then
    perform rally100._fail('both_have_rewards');
  end if;
  if v_rb and not v_ra then
    perform rally100._merge_person(v_b.id, v_a.id, v_me.id);
    perform rally100._audit(v_me.id, v_me.team_id, 'person', v_b.id, 'person_merged',
                            pg_catalog.jsonb_build_object('merged', v_a.id, 'match_id', p_match));
  else
    perform rally100._merge_person(v_a.id, v_b.id, v_me.id);
    perform rally100._audit(v_me.id, v_me.team_id, 'person', v_a.id, 'person_merged',
                            pg_catalog.jsonb_build_object('merged', v_b.id, 'match_id', p_match));
  end if;
  update rally100.possible_matches
     set status = 'linked', resolved_by = v_me.id, resolved_at = pg_catalog.clock_timestamp()
   where id = p_match;
  return pg_catalog.jsonb_build_object('ok', true);
end $$;

/* An incentive award is its own reward record, created already Approved
   (the award IS the approval), for the incentive's prize amount at the
   moment of the award. Rule 12 applies: nobody awards themselves. */
create function rally100.award_incentive(p_incentive uuid, p_rep uuid, p_note text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me   public.profiles := rally100._caller();
  v_i    rally100.incentives%rowtype;
  v_note pg_catalog.text;
  v_team pg_catalog.uuid;
  v_r    rally100.rewards%rowtype;
begin
  perform rally100._require_leader(v_me);
  select * into v_i from rally100.incentives where id = p_incentive;
  if not found then
    perform rally100._deny('not_found');
  end if;
  if not rally100._rep_in_scope(v_me, p_rep) then
    perform rally100._deny('not_found');
  end if;
  select team_id into v_team from public.profiles where id = p_rep;
  if v_team is null then
    perform rally100._deny('not_found');
  end if;
  if p_rep = v_me.id then
    perform rally100._deny('self_involved');
  end if;
  if v_me.role <> 'owner' and exists (select 1 from public.profiles o where o.id = p_rep and o.role = 'owner') then
    perform rally100._deny('owner_only');
  end if;
  if v_i.status <> 'published' then
    perform rally100._fail('not_published');
  end if;
  v_note := rally100._text(p_note, 1000);
  if v_note = '' then
    perform rally100._fail('note_required');
  end if;
  insert into rally100.rewards (kind, team_id, rep_id, incentive_id, amount_cents, status,
                                approved_by, approved_at)
  values ('incentive', v_team, p_rep, v_i.id, v_i.prize_cents, 'approved', v_me.id, pg_catalog.clock_timestamp())
  returning * into v_r;
  perform rally100._reward_event(v_r.id, 'award', null, 'approved', v_me.id, v_note);
  perform rally100._audit(v_me.id, v_me.team_id, 'reward', v_r.id, 'award',
                          pg_catalog.jsonb_build_object('incentive_id', v_i.id, 'rep_id', p_rep,
                                                        'amount_cents', v_i.prize_cents, 'note', v_note));
  return pg_catalog.jsonb_build_object('reward', rally100._reward_json(v_r, v_me));
end $$;

-- -------------------------------------------------------------- 6.4 owner

create function rally100.owner_state()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_me public.profiles := rally100._caller();
begin
  perform rally100._require_owner(v_me);
  return pg_catalog.jsonb_build_object(
    'totals', pg_catalog.jsonb_build_object(
      'reps', (select pg_catalog.count(*) from public.profiles p
                where p.team_id is not null and p.role = 'rep' and not p.disabled),
      'persons', (select pg_catalog.count(*) from rally100.persons p where p.merged_into is null),
      'counted', (select coalesce(pg_catalog.sum(c.o_count), 0)
                    from (select distinct e.rep_id from rally100.entries e) x
                    cross join lateral rally100._rep_counts(x.rep_id) c),
      'introductions', (select pg_catalog.count(*) from rally100.introductions i where i.status = 'introduced'),
      'signed', (select pg_catalog.count(*) from rally100.rewards r
                  where r.kind = 'referral' and r.rep_id is not null and r.reversed_at is null)),
    'reps', (select coalesce(pg_catalog.jsonb_agg(rally100._rep_row(p.id, true) order by rally100._name(p.id), p.id),
                             '[]'::pg_catalog.jsonb)
               from public.profiles p where p.team_id is not null),
    'funnel', (select pg_catalog.jsonb_object_agg(s.stage,
                        (select pg_catalog.count(*) from rally100.persons p
                          where p.merged_into is null and p.stage = s.stage))
                 from pg_catalog.unnest(array['added','intro_planned','introduced','meeting_scheduled',
                        'meeting_completed','commitment_confirmed','agreement_signed','start_confirmed',
                        'arrived']::pg_catalog.text[]) s(stage)),
    'outcomes', (select pg_catalog.jsonb_object_agg(o.outcome,
                          (select pg_catalog.count(*) from rally100.persons p
                            where p.merged_into is null and p.outcome = o.outcome))
                   from pg_catalog.unnest(array['follow_up','not_interested','do_not_contact']::pg_catalog.text[]) o(outcome)),
    'rewards', (select pg_catalog.jsonb_object_agg(st.status, pg_catalog.jsonb_build_object(
                         'count', (select pg_catalog.count(*) from rally100.rewards r
                                    where r.status = st.status and r.reversed_at is null),
                         'amount_cents', (select coalesce(pg_catalog.sum(r.amount_cents), 0) from rally100.rewards r
                                           where r.status = st.status and r.reversed_at is null)))
                  from pg_catalog.unnest(array['in_progress','ready','needs_correction','approved','paid']::pg_catalog.text[]) st(status)),
    'payments', (select coalesce(pg_catalog.jsonb_agg(x.obj order by x.paid_on desc, x.updated_at desc), '[]'::pg_catalog.jsonb)
                   from (select r.paid_on, r.updated_at, pg_catalog.jsonb_build_object(
                                  'reward_id', r.id, 'kind', r.kind, 'rep_id', r.rep_id,
                                  'rep_name', rally100._name(r.rep_id),
                                  'person_name', case when r.person_id is not null then rally100._person_name(r.person_id) end,
                                  'incentive_name', (select i.name from rally100.incentives i where i.id = r.incentive_id),
                                  'amount_cents', r.amount_cents, 'paid_on', r.paid_on, 'paid_method', r.paid_method,
                                  'paid_reference', r.paid_reference, 'paid_by_name', rally100._name(r.paid_by),
                                  'reversed', r.reversed_at is not null) as obj
                           from rally100.rewards r where r.status = 'paid'
                          order by r.paid_on desc, r.updated_at desc limit 50) x),
    'leaders', (select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                         'id', l.id, 'name', rally100._name(l.id),
                         'team_name', (select t.name from public.teams t where t.id = l.team_id),
                         'open_items', (select (select pg_catalog.sum(pg_catalog.jsonb_array_length(q.value))
                                                  from pg_catalog.jsonb_each(rally100._queues(l)) q))::integer)
                         order by rally100._name(l.id), l.id), '[]'::pg_catalog.jsonb)
                  from public.profiles l
                 where l.role in ('leader', 'manager') and l.team_id is not null and not l.disabled),
    'pending_signups', (select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                                 'id', p.id, 'name', rally100._name(p.id), 'email', p.email,
                                 'created_at', p.created_at) order by p.created_at, p.id), '[]'::pg_catalog.jsonb)
                          from public.profiles p where p.team_id is null and not p.disabled),
    'incentives', (select coalesce(pg_catalog.jsonb_agg(rally100._incentive_json(i.id) order by i.created_at, i.id),
                                   '[]'::pg_catalog.jsonb)
                     from rally100.incentives i));
end $$;

create function rally100.owner_contacts()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_me public.profiles := rally100._caller();
begin
  perform rally100._require_owner(v_me);
  return pg_catalog.jsonb_build_object('rows',
    (select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
              'person_id', p.id,
              'name', pg_catalog.btrim(p.first_name || ' ' || p.last_name),
              'phone', coalesce(
                         (select e.phone from rally100.entries e
                           where e.person_id = p.id and e.phone <> '' and e.merged_into is null
                           order by e.created_at, e.id limit 1),
                         (select pg_catalog.min(x.value) from rally100.person_identifiers x
                           where x.person_id = p.id and x.kind = 'phone'), ''),
              'handles', (select coalesce(pg_catalog.jsonb_agg(x.value order by x.value), '[]'::pg_catalog.jsonb)
                            from rally100.person_identifiers x where x.person_id = p.id and x.kind = 'handle'),
              'reps', (select coalesce(pg_catalog.jsonb_agg(distinct rally100._name(e.rep_id)), '[]'::pg_catalog.jsonb)
                         from rally100.entries e where e.person_id = p.id and e.merged_into is null),
              'team_names', (select coalesce(pg_catalog.jsonb_agg(distinct t.name), '[]'::pg_catalog.jsonb)
                               from rally100.entries e join public.teams t on t.id = e.team_id
                              where e.person_id = p.id and e.merged_into is null),
              'stage', p.stage,
              'outcome', p.outcome,
              'interest', p.interest,
              'created_at', p.created_at,
              'requirements_confirmed', rally100._confirmed_count(p.id),
              'reward_status', (select r.status from rally100.rewards r
                                 where r.kind = 'referral' and r.person_id = p.id))
              order by p.created_at, p.id), '[]'::pg_catalog.jsonb)
       from rally100.persons p where p.merged_into is null));
end $$;

create function rally100.owner_rewards(p_status text default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_me public.profiles := rally100._caller();
begin
  perform rally100._require_owner(v_me);
  if p_status is not null and p_status not in ('in_progress', 'ready', 'approved', 'paid', 'needs_correction') then
    perform rally100._fail('invalid_status');
  end if;
  return pg_catalog.jsonb_build_object('rows',
    (select coalesce(pg_catalog.jsonb_agg(rally100._reward_json(r, v_me) order by r.created_at desc, r.id),
                     '[]'::pg_catalog.jsonb)
       from rally100.rewards r where p_status is null or r.status = p_status));
end $$;

/* "Pay issued" is a bookkeeping fact the owner records after paying outside
   the app: only from Approved, once, with a date and a method note. A second
   call is refused with already_paid rather than silently accepted, so a
   double tap can never look like a second payment. */
create function rally100.mark_pay_issued(p_reward uuid, p_paid_on date, p_method text,
                                         p_reference text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me     public.profiles := rally100._caller();
  v_r      rally100.rewards%rowtype;
  v_method pg_catalog.text;
  v_ref    pg_catalog.text;
begin
  perform rally100._require_owner(v_me);
  select * into v_r from rally100.rewards where id = p_reward for update;
  if not found then
    perform rally100._deny('not_found');
  end if;
  if v_r.status = 'paid' then
    perform rally100._fail('already_paid');
  end if;
  if v_r.reversed_at is not null then
    perform rally100._fail('reward_reversed');
  end if;
  if v_r.status <> 'approved' then
    perform rally100._fail('not_approved');
  end if;
  v_method := rally100._text(p_method, 200);
  if v_method = '' then
    perform rally100._fail('method_required');
  end if;
  v_ref := rally100._text(p_reference, 200);
  update rally100.rewards
     set status = 'paid', paid_on = coalesce(p_paid_on, rally100._today()), paid_method = v_method,
         paid_reference = nullif(v_ref, ''), paid_by = v_me.id, updated_at = pg_catalog.clock_timestamp()
   where id = v_r.id;
  perform rally100._reward_event(v_r.id, 'pay', 'approved', 'paid', v_me.id, v_method);
  perform rally100._audit(v_me.id, v_me.team_id, 'reward', v_r.id, 'pay_issued',
                          pg_catalog.jsonb_build_object('paid_on', coalesce(p_paid_on, rally100._today()),
                                                        'method', v_method, 'reference', v_ref));
  select * into v_r from rally100.rewards where id = p_reward;
  return pg_catalog.jsonb_build_object('reward', rally100._reward_json(v_r, v_me));
end $$;

create function rally100.reverse_reward(p_reward uuid, p_reason text, p_rep_reason text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me     public.profiles := rally100._caller();
  v_r      rally100.rewards%rowtype;
  v_reason pg_catalog.text;
  v_rep    pg_catalog.text;
begin
  perform rally100._require_owner(v_me);
  select * into v_r from rally100.rewards where id = p_reward for update;
  if not found then
    perform rally100._deny('not_found');
  end if;
  v_reason := rally100._text(p_reason, 1000);
  if v_reason = '' then
    perform rally100._fail('reason_required');
  end if;
  v_rep := rally100._text(p_rep_reason, 300);
  if v_r.reversed_at is null then
    perform rally100._reverse(v_r.id, v_me.id, v_reason, v_rep, 'reverse');
    perform rally100._audit(v_me.id, v_me.team_id, 'reward', v_r.id, 'reverse',
                            pg_catalog.jsonb_build_object('reason', v_reason, 'rep_reason', v_rep));
  end if;
  select * into v_r from rally100.rewards where id = p_reward;
  return pg_catalog.jsonb_build_object('reward', rally100._reward_json(v_r, v_me));
end $$;

/* RULE 13 — a rep who left or did not come out. Every reward of theirs not
   yet paid is reversed with the internal reason and NO rep-facing reason;
   paid rewards are untouched. The answer is a number for the owner and
   nothing else. */
create function rally100.close_rep_unpaid(p_rep uuid, p_reason text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me public.profiles := rally100._caller();
  v_n  integer := 0;
  r    record;
begin
  perform rally100._require_owner(v_me);
  if p_reason is null or p_reason not in ('left', 'no_show') then
    perform rally100._fail('invalid_reason');
  end if;
  if not exists (select 1 from public.profiles where id = p_rep) then
    perform rally100._deny('not_found');
  end if;
  for r in
    select x.id from rally100.rewards x
     where x.rep_id = p_rep and x.status <> 'paid' and x.reversed_at is null
     order by x.created_at, x.id
  loop
    perform rally100._reverse(r.id, v_me.id, p_reason, '', 'close_unpaid');
    v_n := v_n + 1;
  end loop;
  perform rally100._audit(v_me.id, v_me.team_id, 'rep', p_rep, 'close_unpaid',
                          pg_catalog.jsonb_build_object('reason', p_reason, 'closed', v_n));
  return pg_catalog.jsonb_build_object('closed', v_n);
end $$;

/* The owner's correction when the introduction records were wrong: credit a
   referral to another rep who knows the Person. Not on an approved or paid
   record — reverse it first. */
create function rally100.correct_credit(p_reward uuid, p_rep uuid, p_reason text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me     public.profiles := rally100._caller();
  v_r      rally100.rewards%rowtype;
  v_reason pg_catalog.text;
  v_team   pg_catalog.uuid;
begin
  perform rally100._require_owner(v_me);
  select * into v_r from rally100.rewards where id = p_reward for update;
  if not found then
    perform rally100._deny('not_found');
  end if;
  if v_r.kind <> 'referral' then
    perform rally100._fail('not_referral');
  end if;
  v_reason := rally100._text(p_reason, 1000);
  if v_reason = '' then
    perform rally100._fail('reason_required');
  end if;
  if v_r.status in ('approved', 'paid') then
    perform rally100._fail('locked_reward');
  end if;
  if v_r.reversed_at is not null then
    perform rally100._fail('reward_reversed');
  end if;
  if not exists (select 1 from rally100.entries e
                  where e.rep_id = p_rep and e.person_id = any (rally100._family(v_r.person_id))
                    and e.merged_into is null) then
    perform rally100._fail('not_candidate');
  end if;
  select team_id into v_team from public.profiles where id = p_rep;
  update rally100.rewards
     set rep_id = p_rep, team_id = coalesce(v_team, team_id),
         flags = pg_catalog.array_remove(flags, 'no_intro'), updated_at = pg_catalog.clock_timestamp()
   where id = v_r.id;
  perform rally100._reward_event(v_r.id, 'correct_credit', v_r.status, v_r.status, v_me.id, v_reason);
  perform rally100._audit(v_me.id, v_me.team_id, 'reward', v_r.id, 'correct_credit',
                          pg_catalog.jsonb_build_object('from_rep', v_r.rep_id, 'to_rep', p_rep, 'reason', v_reason));
  perform rally100._referral_eval(v_r.person_id, v_me.id);
  select * into v_r from rally100.rewards where id = p_reward;
  return pg_catalog.jsonb_build_object('reward', rally100._reward_json(v_r, v_me));
end $$;

create function rally100.clear_dnc(p_person uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me public.profiles := rally100._caller();
  v_p  rally100.persons%rowtype;
begin
  perform rally100._require_owner(v_me);
  v_p := rally100._person_for_write(v_me, p_person);
  if v_p.outcome = 'do_not_contact' then
    update rally100.persons set outcome = null, outcome_date = null, outcome_note = '',
                                updated_at = pg_catalog.clock_timestamp()
     where id = p_person;
    perform rally100._audit(v_me.id, v_me.team_id, 'person', p_person, 'outcome',
                            pg_catalog.jsonb_build_object('from', 'do_not_contact', 'to', null));
    perform rally100._settle_person_reps(p_person);
  end if;
  return pg_catalog.jsonb_build_object('person', rally100._person_json(p_person));
end $$;

/* Create (no id) or update (id) an incentive. Absent keys leave a field
   alone on update. A published incentive must have a picture: reps see the
   picture first. */
create function rally100.incentive_save(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me     public.profiles := rally100._caller();
  v_old    rally100.incentives%rowtype;
  v_id     pg_catalog.uuid;
  v_new    boolean;
  v_name   pg_catalog.text;
  v_pics   pg_catalog.jsonb;
  v_prize  integer;
  v_how    pg_catalog.text;
  v_status pg_catalog.text;
begin
  perform rally100._require_owner(v_me);
  if p is null or pg_catalog.jsonb_typeof(p) <> 'object' then
    perform rally100._fail('invalid_payload');
  end if;
  v_new := (p ->> 'id') is null;
  if not v_new then
    if (p ->> 'id') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
      perform rally100._deny('not_found');
    end if;
    v_id := (p ->> 'id')::pg_catalog.uuid;
    select * into v_old from rally100.incentives where id = v_id for update;
    if not found then
      perform rally100._deny('not_found');
    end if;
  end if;

  v_name := case when p ? 'name' then rally100._clean_name(p ->> 'name') else coalesce(v_old.name, '') end;
  if v_name = '' then
    perform rally100._fail('name_required');
  end if;
  if pg_catalog.char_length(v_name) > 80 then
    perform rally100._fail('name_too_long');
  end if;
  v_pics := case when p ? 'pictures' then rally100._check_pictures(p -> 'pictures')
                 else coalesce(v_old.pictures, '[]'::pg_catalog.jsonb) end;
  if p ? 'prize_cents' and pg_catalog.jsonb_typeof(p -> 'prize_cents') <> 'null' then
    if pg_catalog.jsonb_typeof(p -> 'prize_cents') <> 'number'
       or (p ->> 'prize_cents') !~ '^[0-9]{1,9}$' then
      perform rally100._fail('invalid_prize');
    end if;
    v_prize := (p ->> 'prize_cents')::integer;
  else
    v_prize := v_old.prize_cents;
  end if;
  if v_prize is null then
    perform rally100._fail('prize_required');
  end if;
  v_how := case when p ? 'how_to_earn' then rally100._text(p ->> 'how_to_earn', 200)
                else coalesce(v_old.how_to_earn, '') end;
  v_status := case when p ? 'status' then p ->> 'status' else coalesce(v_old.status, 'draft') end;
  if v_status is null or v_status not in ('draft', 'published', 'off') then
    perform rally100._fail('invalid_status');
  end if;
  if v_status = 'published' and pg_catalog.jsonb_array_length(v_pics) < 1 then
    perform rally100._fail('picture_required');
  end if;

  if v_new then
    insert into rally100.incentives (name, pictures, prize_cents, how_to_earn, status, created_by)
    values (v_name, v_pics, v_prize, v_how, v_status, v_me.id)
    returning id into v_id;
    perform rally100._audit(v_me.id, v_me.team_id, 'incentive', v_id, 'incentive_created',
                            pg_catalog.jsonb_build_object('name', v_name, 'prize_cents', v_prize, 'status', v_status));
  else
    update rally100.incentives
       set name = v_name, pictures = v_pics, prize_cents = v_prize, how_to_earn = v_how, status = v_status,
           updated_at = pg_catalog.clock_timestamp()
     where id = v_id;
    perform rally100._audit(v_me.id, v_me.team_id, 'incentive', v_id, 'incentive_updated',
                            pg_catalog.jsonb_build_object('name', v_name, 'prize_cents', v_prize, 'status', v_status,
                                                          'from_prize_cents', v_old.prize_cents,
                                                          'from_status', v_old.status));
  end if;
  return pg_catalog.jsonb_build_object('incentive', rally100._incentive_json(v_id));
end $$;

create function rally100.incentive_status(p_incentive uuid, p_status text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_me public.profiles := rally100._caller();
  v_i  rally100.incentives%rowtype;
begin
  perform rally100._require_owner(v_me);
  select * into v_i from rally100.incentives where id = p_incentive for update;
  if not found then
    perform rally100._deny('not_found');
  end if;
  if p_status is null or p_status not in ('draft', 'published', 'off') then
    perform rally100._fail('invalid_status');
  end if;
  if p_status = 'published' and pg_catalog.jsonb_array_length(v_i.pictures) < 1 then
    perform rally100._fail('picture_required');
  end if;
  if p_status <> v_i.status then
    update rally100.incentives set status = p_status, updated_at = pg_catalog.clock_timestamp()
     where id = p_incentive;
    perform rally100._audit(v_me.id, v_me.team_id, 'incentive', p_incentive, 'incentive_status',
                            pg_catalog.jsonb_build_object('from', v_i.status, 'to', p_status));
  end if;
  return pg_catalog.jsonb_build_object('incentive', rally100._incentive_json(p_incentive));
end $$;

-- ============================================================= privileges ===
/* Floor first: nothing in rally100 is reachable by any client role, then
   the exact list of doors is opened.

   service_role is named explicitly. Supabase's default privileges grant it
   (and anon and authenticated) everything on new objects in public, and a
   project can carry wider defaults; `revoke ... from public` alone does not
   remove a grant made to a named role. The service key has no business
   reading this schema's tables or calling its internals directly: the
   internals run as the owner, inside the doors, and lose nothing. */
revoke all on all tables    in schema rally100 from public, anon, authenticated, service_role;
revoke all on all sequences in schema rally100 from public, anon, authenticated, service_role;
revoke all on all functions in schema rally100 from public, anon, authenticated, service_role;
revoke all on schema rally100 from public, anon, authenticated, service_role;

-- PostgREST resolves rally100.<name> as the authenticated role; USAGE lets it
-- name the functions. It grants no table, no data and no CREATE.
grant usage on schema rally100 to authenticated;

-- The thirty-nine API functions of API.md section 6, and nothing else.
-- Every helper whose name starts with _ stays executable by its owner only.
grant execute on function rally100.whoami()                                    to authenticated;
grant execute on function rally100.accept_ack(integer)                         to authenticated;
grant execute on function rally100.rep_state()                                 to authenticated;
grant execute on function rally100.save_entry(jsonb)                           to authenticated;
grant execute on function rally100.resolve_duplicate(uuid, text, text)         to authenticated;
grant execute on function rally100.remove_entry(uuid)                          to authenticated;
grant execute on function rally100.restore_entry(uuid)                         to authenticated;
grant execute on function rally100.plan_intro(uuid)                            to authenticated;
grant execute on function rally100.record_intro(uuid, text, text, text, date)  to authenticated;
grant execute on function rally100.set_follow_up(uuid, date, text)             to authenticated;
grant execute on function rally100.tell_leader(uuid, text)                     to authenticated;
grant execute on function rally100.award_badge(text)                           to authenticated;
grant execute on function rally100.team_state()                                to authenticated;
grant execute on function rally100.person_detail(uuid)                         to authenticated;
grant execute on function rally100.confirm_intro_received(uuid, uuid)          to authenticated;
grant execute on function rally100.set_stage(uuid, text, date, text)           to authenticated;
grant execute on function rally100.schedule_meeting(uuid, timestamptz, text, text) to authenticated;
grant execute on function rally100.set_requirement(uuid, integer, boolean, date, text, date, text, boolean) to authenticated;
grant execute on function rally100.set_outcome(uuid, text, date, text)         to authenticated;
grant execute on function rally100.set_interest(uuid, text)                    to authenticated;
grant execute on function rally100.set_next_action(uuid, text, uuid, date)     to authenticated;
grant execute on function rally100.add_note(uuid, text)                        to authenticated;
grant execute on function rally100.mark_messages_read(uuid)                    to authenticated;
grant execute on function rally100.rep_list(uuid)                              to authenticated;
grant execute on function rally100.record_spot_check(uuid, jsonb, text)        to authenticated;
grant execute on function rally100.review_reward(uuid, text, text)             to authenticated;
grant execute on function rally100.resolve_correction(uuid, text)              to authenticated;
grant execute on function rally100.link_persons(uuid, text)                    to authenticated;
grant execute on function rally100.award_incentive(uuid, uuid, text)           to authenticated;
grant execute on function rally100.owner_state()                               to authenticated;
grant execute on function rally100.owner_contacts()                            to authenticated;
grant execute on function rally100.owner_rewards(text)                         to authenticated;
grant execute on function rally100.mark_pay_issued(uuid, date, text, text)     to authenticated;
grant execute on function rally100.reverse_reward(uuid, text, text)            to authenticated;
grant execute on function rally100.close_rep_unpaid(uuid, text)                to authenticated;
grant execute on function rally100.correct_credit(uuid, uuid, text)            to authenticated;
grant execute on function rally100.clear_dnc(uuid)                             to authenticated;
grant execute on function rally100.incentive_save(jsonb)                       to authenticated;
grant execute on function rally100.incentive_status(uuid, text)                to authenticated;

commit;
